  senseState: SenseState | undefined = undefined;
  /** 静态地图以 mapId 为实例；刷新/往返地图均不撤销显形，无奖励归属。 */
  senseRevealed: Record<string, true> | undefined = undefined;
  /** 已付料的这一炉；刷新继续火候，结算前清空防止重复领奖。 */
