  private talismanFx = new Set<Phaser.GameObjects.Sprite>();
  private talismanBuffFx = new Map<string, Phaser.GameObjects.Sprite>();
  private talismanBuffIcons = new Map<string, Phaser.GameObjects.Image>();
  private talismanReturnFx?: Phaser.GameObjects.Sprite;
  shop!: ShopPanel;
  attrPanel!: AttrPanel;
  inventoryPanel!: InventoryPanel;
  equipPanel!: EquipPanel;
  private interactionPrompts: { object: MapObj; prompt: Phaser.GameObjects.Container; marker?: Phaser.GameObjects.Image | Phaser.GameObjects.Text }[] = [];
  private sectTitle!: Phaser.GameObjects.Text;
  private sectBadge!: Phaser.GameObjects.Image;
  private portalVisuals: { object: MapObj; art: Phaser.GameObjects.Ellipse | Phaser.GameObjects.Sprite; label?: Phaser.GameObjects.Text }[] = [];
  private seclusionLabels: Phaser.GameObjects.Text[] = [];

  constructor() { super('game'); (window as any).__scene = this; }

  /** Scene 实例会被 restart 复用；这里只重置本张图的状态，不能复用旧物理世界的引用。 */
  private resetRunState() {
    this.towerRoomView?.destroy(); this.towerRoomView = undefined;
    this.towerGate = undefined; this.towerBusy = false;
    this.towerOwnsPause = false; this.towerOwnsTimerPause = false;
    this.secretNestRoomView?.destroy(); this.secretNestRoomView = undefined;
    this.secretNestRoom = undefined; this.secretNestOwnsPause = false; this.secretNestOwnsTimerPause = false;
    this.senseUi?.destroy(); this.senseUi = undefined;
    this.encounterUi?.destroy(); this.encounterUi = undefined;
    this.encounterRuntime?.destroy();
    this.unregisterEncounterSense?.(); this.unregisterEncounterSense = undefined;
    for (const prop of this.encounterProps.values()) prop.sprite.destroy();
    this.encounterProps.clear();
    this.encounterRuntime = undefined;
    this.encounterOwnsPause = false;
    this.sense?.clearIntel();
    this.sense = undefined!; this.senseMap = undefined!;
    this.senseCueDepth = 0; this.senseBusyProviders.clear();
    this.clearShots();
    this.mobs = []; this.logs = []; this.logBadges.clear();
    this.nextPickAt = 0; this.openedChests = new Set();
    this.travelling = false; this.curZone = undefined; this.nextDailyUpdateAt = 0;
    this.playerPhysicsAccumulator = 0; this.playerPhysicsAdvanced = false; this.playerInput.clear();
    this.sectTrial = undefined; this.trial = undefined; this.bossOverride = null;
    this.trialObjects = undefined; this.stealth = undefined; this.atSectTrialEntrance = false;
    this.npcMarks = []; this.hudTexts = undefined; this.hudKit = undefined; this.bossIntroShown = false;
    this.interactionPrompts = []; this.portalVisuals = []; this.seclusionLabels = [];
    this.backgroundArt?.destroy(); this.propLayout?.destroy(); this.environmentArt?.destroy();
    this.backgroundArt = undefined; this.propLayout = undefined; this.environmentArt = undefined;
    for (const object of this.backgroundObjects) object.destroy();
    this.backgroundObjects = []; this.parallax = [];

    // 必建对象在 create 中按依赖顺序重建；先释放旧引用，避免部分 create 失败后使用上一图对象。
    this.map = undefined!; this.player = undefined!; this.sectGrowth = undefined!;
    this.drops = undefined!; this.keys = undefined!; this.gathering = undefined!;
    this.quests = undefined!; this.combat = undefined!; this.alchemySystem = undefined!;
    this.hud = undefined!; this.hudText = undefined!; this.debugText = undefined!; this.helpText = undefined!;
    this.sectTitle = undefined!; this.sectBadge = undefined!; this.invText = undefined!; this.tracker = undefined!;
    this.gourd = undefined!; this.gourdTip = undefined!; this.bossName = undefined!; this.bossHpText = undefined!;
    this.dialog = undefined!; this.skillBar = undefined!; this.skillWindow = undefined!;
    this.alchemy = undefined!; this.shop = undefined!; this.attrPanel = undefined!;
    this.inventoryPanel = undefined!; this.equipPanel = undefined!;

    // 制符为每图重建：系统实例和火符弹体不跨图保留；进度/冷却在 prog。
    this.clearTalismanFx();
    this.talismanSystem = undefined!; this.talismanUse = undefined!; this.talismanCastText = undefined;

    // prog 由 registry 持有并沿用角色/存档；不能在换图时新建或重置角色进度。
    // mpPool 是跨图回蓝的小数余量，清零会少回灵力；breakthroughNotified 是会话内一次提示。
    // nextAgeUpdateAt 使用游戏累计时钟，保留跨图的 60 秒寿元结算/存档节流。
    // registry 中的试炼交接、宝箱存档和环境偏好也有意跨图保留，由各自流程读写。
  }

  private clearShots() {
    for (const shot of this.shots) this.removeShot(shot);
    this.shots = []; this.shotOf.clear(); this.shotGroup = undefined;
  }

  private removeShot(shot: Shot) {
    this.shotOf.delete(shot.sprite);
    shot.dead = true;
    // destroy 后 Phaser 会清掉 scene/body；重复清理不再访问已销毁的物理体。
    if (shot.sprite.scene) shot.sprite.destroy();
  }

  private createDebugClass() {
    const prog = new Progress();
    // 独立调试档不写 localStorage；换图继续用 registry 内同一角色。
    Object.defineProperty(prog, 'save', { value: (options?: { async: true }) => options?.async ? Promise.resolve(true) : true });
    prog.level = 29;
    prog.advanceClass(DEBUG_CLASS!.id);
    for (const def of prog.classSkills) prog.grantSkill(def.id, 1);
    prog.addItem('talisman_paper', 999);
    prog.hp = prog.maxHp; prog.mp = prog.maxMp;
    return prog;
  }

  preload() {
    for (const a of AREAS) {
      loadOptionalImage(this, `tiles_${a}`, `art/tiles/tiles_${a}.png`);
      loadOptionalSpritesheet(this, `tiles_${a}_ss`, `art/tiles/tiles_${a}.png`, { frameWidth: 32, frameHeight: 32 });
    }
    for (const metadata of TILE_METADATA) loadOptionalJson(this, metadata.key, metadata.path);
    for (const config of BACKGROUND_CONFIGS) loadOptionalJson(this, config.key, config.path);
    for (const layout of PROP_LAYOUTS) loadOptionalJson(this, layout.key, layout.path);
    for (const background of BACKGROUNDS) loadOptionalImage(this, background.key, background.path);
    for (const k of ATLASES) {
      if (loadOptionalAtlas(this, k, `art/sprites/${k}.png`, `art/sprites/${k}.json`))
        loadOptionalJson(this, `${k}_anims`, `art/sprites/${k}.anims.json`);
    }
    if (!this.textures.exists('icons_skills'))
      this.load.atlas('icons_skills', 'art/icons/icons_skills.png', 'art/icons/icons_skills.json');
    for (const icon of SKILL_ICONS) loadOptionalImage(this, icon.key, icon.path);
    // 葫芦三态：hud/ 目录里还没有，继续读 art/icons/ui/
    for (const tier of ['empty', 'half', 'full']) this.load.image(`icon_overflow_gourd_${tier}`, `art/icons/ui/icon_overflow_gourd_${tier}.png`);
    if (!this.textures.exists('icons_items'))
      this.load.atlas('icons_items', 'art/icons/icons_items.png', 'art/icons/icons_items.json');
    preloadHud(this);
    preloadAlchemy(this);
  }

  create(data: { map?: string; portal?: string; pos?: { x: number; y: number }; talismanReturnLand?: boolean; secretTheme?: string }) {
    // main 正常会注入异步读档；直接启动场景时也不能退回同步 IDB 读取。
    if (featureEnabled('indexedDbSaves') && !this.registry.get('progress')) {
      this.loadingProgress = true;
      let cancelled = false;
      const cancel = () => { cancelled = true; };
      this.events.once(Phaser.Scenes.Events.SHUTDOWN, cancel);
      void Progress.load({ async: true }).then(progress => {
        this.events.off(Phaser.Scenes.Events.SHUTDOWN, cancel);
        if (cancelled) return;
        this.registry.set('progress', progress);
        this.scene.restart(data);
      });
      return;
    }
    this.loadingProgress = false;
    this.resetRunState();
    this.physics.disableUpdate();
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => this.clearShots());
    syncTalismanMapAvailability();
    installKeyGuard();
    for (const k of ATLASES) {
      const a = this.cache.json.get(`${k}_anims`);
      if (!a || !this.textures.exists(k)) continue;
      for (const an of a.anims) if (!this.anims.exists(an.key))
        this.anims.create({ key: an.key, frames: an.frames.map((f: string) => ({ key: k, frame: f })), frameRate: an.frameRate, repeat: an.repeat });
    }
    if (!DEBUG_CLASS && new URLSearchParams(location.search).get('reset') === '1' && !this.registry.get('progress')) Progress.reset();
    this.prog = this.registry.get('progress') ?? (DEBUG_CLASS ? this.createDebugClass() : Progress.load());
    // 页面刷新中断一局；保存的返回落点使失败/刷新都能再次找长老确认。
    const pendingQuest = this.prog.pendingSectTrial ? TRIALS[this.prog.pendingSectTrial.id]?.quest : undefined;
    const pendingClass = pendingQuest ? classForQuest(pendingQuest) : undefined;
    const pendingAllowed = !this.prog.job && featureEnabled('fiveSectClasses') && featureEnabled('v05Maps')
      && pendingClass && this.prog.quests[pendingQuest!]?.state === 'active'
      && this.prog.count('five_sect_token') > 0 && this.prog.selectedSect === pendingClass.sect;
    const interrupted = this.prog.pendingSectTrial && (!this.registry.get('sectTrialEntering') || !pendingAllowed);
    if (interrupted && this.prog.pendingSectTrial) {
      const at = sectTrialReturnPosition(this.prog.pendingSectTrial.returnPosition);
      data = { map: at.mapId, pos: { x: at.x, y: at.y } };
      this.prog.pendingSectTrial = null; this.prog.endTrialSkills();
      this.prog.hp = this.prog.maxHp; this.prog.mp = this.prog.maxMp;
      this.rememberPosition(at.mapId, at.x, at.y);
    }
    this.registry.remove('sectTrialEntering');
    this.sectGrowth = new SectGrowth(this.prog);
    this.quests = new QuestSystem(this.prog);
    const stopClosedTips = this.quests.onBlocked(tip => this.log(tip.text, '#aaaaaa'));
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, stopClosedTips);
    this.registry.set('progress', this.prog);
    this.openedChests = new Set(this.prog.openedChests);
    this.registry.set('chests', this.openedChests);
    registerHudFonts(this);
    registerAlchemy(this);

    const q = new URLSearchParams(location.search).get('map');
    const debugTrial = DEBUG_CLASS && QUESTS_REF[DEBUG_CLASS.joinQuest]?.objectives.find(o => o.type === 'trial')?.trial;
    const debugMap = DEBUG_CLASS && (TILED_MAPS[DEBUG_CLASS.map ?? ''] ? DEBUG_CLASS.map : debugTrial ? TRIALS[debugTrial]?.map : undefined);
    let mapId = data.map ?? (q === 'test' || q === 'field' ? 'field_test' : q && TILED_MAPS[q] ? q : debugMap ?? this.prog.position?.mapId ?? 'qingyun_village');
    mapId = TILED_MAPS[mapId] ? mapId : (MAP_FALLBACK[mapId] ?? mapId);
    // 本版本没有的地图（存档或传送门指过去）一律回青云村，不再掉进测试图
    if (!TILED_MAPS[mapId] && mapId !== 'field_test') { mapId = 'qingyun_village'; data.portal = undefined; }
    // URL、旧落点或旧入口误入试炼图时，非本局玩家优先落回已注册山门。
    if (!DEBUG_CLASS && !this.prog.pendingSectTrial) {
      const at = sectTrialReturnPosition({ mapId, x: 0, y: 0 });
      if (at.mapId !== mapId) {
        mapId = at.mapId;
        data = { map: mapId, pos: { x: at.x, y: at.y } };
      }
    }

    const area = MAP_AREA[mapId] ?? 'qingyun';
    this.drawBackground(area, TILED_MAPS[mapId]?.width * FEEL.tile || Math.max(...FIELD_TEST.rows.map(row => row.length)) * FEEL.tile,
      TILED_MAPS[mapId]?.height * FEEL.tile || FIELD_TEST.rows.length * FEEL.tile);
    this.map = TILED_MAPS[mapId] ? buildTiledMap(this, TILED_MAPS[mapId], `tiles_${area}`)
      : buildCharMap(this, FIELD_TEST.id, FIELD_TEST.name, FIELD_TEST.rows, FIELD_TEST.portals, `tiles_${area}`);
    this.atSectTrialEntrance = !DEBUG_CLASS && !this.prog.pendingSectTrial
      && Object.values(TRIALS).some(def => def.quest && def.map === this.map.id);
    this.propLayout?.destroy();
    this.propLayout = new PropLayout(this, mapId, this.cache.json.get(`props_${area}_layout`));
    this.physics.world.setBounds(0, 0, this.map.width, this.map.height + 200);
    // 地图 npc 对象的 phaseMin / phaseMax：不在当前版本阶段的不创建（没填不限制）
    this.map.objects = this.map.objects.filter(o => o.type !== 'npc' || inPhase(o.props));
    this.configureEnvironment(this.cache.json.get(`bg_${area}_config`)?.environment);
    this.mountDailyEnvoys();
    this.mountSectTrialEntrance();
    this.senseMap = new SenseMapAdapter(this);
    this.map.objects.forEach(o => this.drawObject(o, data.secretTheme));
    // zone 在 MapBuilder 中独立保留；这里只绘制皮肤，不增加伤害或触发规则。
    this.drawSecretTrapZones(data.secretTheme);

    const savedPosition = !data.map && !q && this.prog.position?.mapId === mapId ? this.prog.position : undefined;
    const at = data.portal ? this.map.objects.find(o => o.type === 'portal' && o.name === data.portal) : data.pos ?? savedPosition;
    this.player = new Player(this, at ? at.x : this.map.spawn.x, at ? at.y : this.map.spawn.y);
    this.player.hp = this.prog.hp; this.player.maxHp = this.prog.maxHp;
    this.player.getMovePoints = () => this.prog.currentMovePoints();
    this.player.getAirJumpBonus = () => ({ extra: this.prog.passiveBonus('extraAirJumps'), distanceRatio: this.prog.passiveBonus('doubleJumpDistanceRatio') });
    this.player.getSkillAlpha = () => this.prog.hasBuffEffect('invisible') ? 0.35 : 1;
    this.player.getAppearance = () => this.prog.appearance;
    this.player.syncAppearance();
    this.gathering = new Gathering(this);
    this.combat = new SkillCombat(this);
    this.events.on('skill:cast', () => this.interruptTalisman('attack'));
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => this.events.removeAllListeners('skill:cast'));

    const oneWayCheck = (a: any, plat: any) => {
      const body: Phaser.Physics.Arcade.Body = a.body;
      if (a === this.player && (this.player.state2 === 'rope' || this.time.now < this.player.dropUntil)) return false;
      const top = (plat.body as Phaser.Physics.Arcade.StaticBody).top;
      return body.velocity.y >= 0 && body.prev.y + body.height <= top + 2;
    };
    this.physics.add.collider(this.player, this.map.solids);
    this.physics.add.collider(this.player, this.map.oneWays, () => { if (this.player.body.touching.down) this.player.oneWayAt = this.time.now; }, oneWayCheck);

    for (const sp of this.map.trial ? [] : this.map.spawns) {
      const def = MONSTERS[sp.monster];
      if (!def) { console.warn(`[spawn] 没有怪物 ${sp.monster}`); continue; }
      if (sp.monster === 'demon_fox' && !featureEnabled('foxBoss')) continue;
      // 首领区：接了 unlockQuest 才刷（任务系统 v0.3 接入，v0.2 先不刷）
      const zone = this.map.zones.find(z => sp.x >= z.x && sp.x <= z.x + z.w && sp.y >= z.y && sp.y <= z.y + z.h);
      if (zone?.props.unlockQuest && !this.quests.isActive(zone.props.unlockQuest)) continue;
      for (let i = 0; i < sp.count; i++) {
        // 刷怪点是一段平台宽度，怪在这段上均匀打散
        const x = sp.w > 0 ? sp.x + (sp.w * (i + 0.5)) / sp.count + Phaser.Math.Between(-16, 16) : sp.x + i * 24;
        const m = new Monster(this, x, sp.y, def);
        if (sp.w > 0) m.patrolBounds = [sp.x, sp.x + sp.w];
        this.wireMob(m);
        this.mobs.push(m);
      }
    }
    this.physics.add.collider(this.mobs, this.map.solids);
    this.physics.add.collider(this.mobs, this.map.oneWays, undefined, oneWayCheck);
    this.physics.add.overlap(this.player, this.mobs, (_p, mo) => {
      const m = mo as Monster;
      if (m.dead || m.suppressTouch || !m.def.touchDamage || this.map.safeZone && false) return;
      this.hurtPlayer(this.prog.damageFrom(m.def.atk, m.def.touchDamageMul ?? 1), m.x, m.def.knockback);
    });

    this.drops = this.physics.add.group();
    this.physics.add.collider(this.drops, this.map.solids);
    this.physics.add.collider(this.drops, this.map.oneWays, undefined, oneWayCheck);

    this.player.onAttack = rect => this.doAttack(rect);
    this.player.on('doublejump', () => this.puff(this.player.x, this.player.y - 10));

    const K = Phaser.Input.Keyboard.KeyCodes;
    this.keys = this.input.keyboard!.addKeys({
      left: K.LEFT, right: K.RIGHT, up: K.UP, down: K.DOWN, alt: K.ALT, space: K.SPACE, c: K.C,
      ctrl: K.CTRL, x: K.X, z: K.Z, f1: K.F1, r: K.R, one: K.ONE, two: K.TWO, three: K.THREE, four: K.FOUR, five: K.FIVE, i: K.I,
      a: K.A, s: K.S, d: K.D, f: K.F, g: K.G, h: K.H, q: K.Q, w: K.W, k: K.K, l: K.L, p: K.P, e: K.E, esc: K.ESC,
    }, true) as any;

    const cam = this.cameras.main;
    cam.setBounds(0, 0, this.map.width, this.map.height + HUD_RESERVE);
    addFloorStrip(this, this.map.width, this.map.height, area);
    cam.startFollow(this.player, true, 0.12, 0.1, 0, 40);
    cam.fadeIn(250);

    this.hud = this.add.graphics().setScrollFactor(0).setDepth(100);
    this.hudText = this.add.text(0, 0, '', { fontFamily: 'sans-serif', fontSize: '14px', color: '#ffffff' }).setScrollFactor(0).setDepth(101);
    this.sectTitle = this.add.text(1264, 164, '', { fontFamily: HUD_FONT, fontSize: '13px', color: INK,
      backgroundColor: '#faf2dcee', padding: { x: 6, y: 4 }, lineSpacing: 3 }).setOrigin(1, 0).setScrollFactor(0).setDepth(101).setVisible(false);
    this.sectBadge = this.add.image(0, 0, '__DEFAULT').setName('sect-rank-hud').setDisplaySize(24, 24).setScrollFactor(0).setDepth(101).setVisible(false);
    this.debugText = this.add.text(16, 200, '', { fontFamily: 'monospace', fontSize: '12px', color: '#1d2a3a', backgroundColor: '#ffffffaa', padding: { x: 6, y: 4 } }).setScrollFactor(0).setDepth(100).setVisible(false);
    this.add.text(16, 14, `${this.map.name}${this.map.safeZone ? '（安全区）' : ''}`, { fontFamily: 'sans-serif', fontSize: '18px', color: '#1d2a3a', stroke: '#ffffff', strokeThickness: 4 }).setScrollFactor(0).setDepth(100);
    this.helpText = this.add.text(1264, 14, '',
      { fontFamily: 'sans-serif', fontSize: '13px', color: '#1d2a3a', backgroundColor: '#ffffffaa', padding: { x: 8, y: 6 }, align: 'right' })
      .setOrigin(1, 0).setScrollFactor(0).setDepth(100);
    this.refreshHelpText();
    this.dialog = new DialogBox(this);
    this.alchemySystem = new AlchemySystem(this.prog, this.quests);
    this.alchemy = new AlchemyPanel(this, this.prog, this.alchemySystem);
    if (this.alchemySystem.active) this.alchemy.open(this.alchemySystem.active.furnaceId);
    if (featureEnabled('talismanCraft')) this.setupTalisman();
    this.shop = new ShopPanel(this, this.prog, () => this.sectGrowth, { log: (text, color) => this.log(text, color),
      require: (name, npcId) => this.requireFeature(name, npcId), rankIcon: rankId => this.sectRankBadgeKey(rankId) });
    this.skillBar = new SkillBar(this);
    this.skillWindow = new SkillWindow(this, () => this.prog, id => this.tryAddPoint(id));
    this.attrPanel = new AttrPanel(this, this.prog, () => {
      this.player.maxHp = this.prog.maxHp; this.player.hp = this.prog.hp;
      this.skillWindow.refresh();
    }, { senseEnabled: () => featureEnabled('spiritScan'), sensePreview: () => this.sense?.preview(),
      senseKeyHint: () => this.senseUi?.keyHint() ?? t('sense.ui.no_binding'),
      senseBlockText: preview => this.senseUi?.blockText(preview) ?? t(preview.blockKey ?? 'sense.block.unavailable') });
    const equipmentChanged = () => {
      this.player.syncAppearance();
      this.player.maxHp = this.prog.maxHp; this.player.hp = this.prog.hp;
      this.skillWindow.refresh();
    };
    this.inventoryPanel = new InventoryPanel(this, this.prog, { onChanged: equipmentChanged,
      openAlchemy: id => this.openAlchemy(id), openSectToken: () => this.openSectToken(),
      useTalisman: (id, quality) => featureEnabled('indexedDbSaves') ? this.useTalismanAsync(id, quality) : this.useTalisman(id, quality),
      bindTalisman: (slot, id, quality) => this.prog.bindTalismanSlot(slot, id, quality) });
    this.equipPanel = new EquipPanel(this, this.prog, equipmentChanged);
    this.skillBar.onSlot = i => { if (this.skillWindow.open) this.skillWindow.assign(i); };
    this.maybeSpTip();
    this.tracker = this.add.text(16, 44, '', { fontFamily: 'sans-serif', fontSize: '13px', color: '#ffffff', backgroundColor: '#1d2a3aaa', padding: { x: 8, y: 6 }, lineSpacing: 3 }).setScrollFactor(0).setDepth(100);
    this.input.keyboard!.addKey(K.ENTER).on('down', () => {
      if (this.encounterUi?.isOpen()) this.encounterUi.advance(); else this.dialog.advance();
    });
    this.invText = this.add.text(1264, 130, '', { fontFamily: 'sans-serif', fontSize: '14px', color: '#ffffff', backgroundColor: '#1d2a3acc', padding: { x: 10, y: 8 } }).setOrigin(1, 0).setScrollFactor(0).setDepth(100).setVisible(false);
    this.gourd = this.add.image(1220, 718, 'icon_overflow_gourd_empty').setOrigin(0.5, 1).setScrollFactor(0).setDepth(103).setVisible(false).setInteractive({ useHandCursor: true });
    this.gourdTip = this.add.text(1220, 680, '', { fontFamily: 'sans-serif', fontSize: '12px', color: '#fff8e8', backgroundColor: '#1d2a3aee', padding: { x: 6, y: 3 } }).setOrigin(1, 1).setScrollFactor(0).setDepth(140).setVisible(false);
    this.gourd.on('pointerover', () => { if (this.gourd.visible) this.gourdTip.setVisible(true); });
    this.gourd.on('pointerout', () => this.gourdTip.setVisible(false));
    this.bossName = this.add.text(0, 0, '', { fontFamily: 'serif', fontSize: '18px', color: '#fff6e8', stroke: '#3a1020', strokeThickness: 4 }).setScrollFactor(0).setDepth(130).setVisible(false);
    this.bossHpText = this.add.text(0, 0, '', { fontFamily: 'sans-serif', fontSize: '13px', color: '#ffe0e0', stroke: '#000000', strokeThickness: 3 }).setScrollFactor(0).setDepth(130).setVisible(false);
    this.buildHudKit();
    this.setupTrial(mapId);
    const pending = this.prog.pendingSectTrial;
    const sectDef = pending ? TRIALS[pending.id] : undefined;
    if (sectDef && sectDef.map === mapId && featureEnabled('fiveSectClasses') && featureEnabled('v05Maps')) {
      this.prog.beginTrialSkills(sectDef.grantSkills ?? []);
      this.sectTrial = new SectTrial(this, sectDef);
      if (sectDef.sect === 'youying') this.log(sectTrialText('trial.sect_youying_skills',
        '已获得试炼技能：隐息术（剩余 {n} 次）、影遁', { n: this.prog.trialSkillCharges('phantom_cloak') ?? 0 }), '#d4c0ff');
    }
    this.trialObjects = new SectTrialObjects(this);
    this.stealth = new StealthVision(this);
    this.stealth.update(0, false);
    this.setupSense();
    this.senseUi = new SenseUi(this, () => this.senseBusy());
    this.encounterUi = new EncounterUi(this);
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      // 刷新/销毁保留可恢复节点；明确跨图由 travel/新地图 enter 结算 missed。
      this.encounterRuntime?.destroy();
      this.unregisterEncounterSense?.(); this.unregisterEncounterSense = undefined;
      for (const prop of this.encounterProps.values()) prop.sprite.destroy();
      this.encounterProps.clear();
      this.encounterRuntime = undefined;
      if (this.encounterOwnsPause) { this.physics.resume(); this.encounterOwnsPause = false; }
      this.secretNestRoomView?.destroy(); this.secretNestRoomView = undefined;
      this.secretNestRoom = undefined;
      if (this.secretNestOwnsPause) { this.physics.resume(); this.secretNestOwnsPause = false; }
      if (this.secretNestOwnsTimerPause) { this.time.paused = false; this.secretNestOwnsTimerPause = false; }
      this.towerRoomView?.destroy(); this.towerRoomView = undefined;
      this.towerGate = undefined; this.towerBusy = false;
      if (this.towerOwnsPause) { this.physics.resume(); this.towerOwnsPause = false; }
      if (this.towerOwnsTimerPause) { this.time.paused = false; this.towerOwnsTimerPause = false; }
      this.events.off('encounter:ui-advance', this.advanceEncounter, this);
      this.events.off('encounter:ui-choice', this.chooseEncounter, this);
      this.events.off('encounter:ui-puzzle', this.puzzleEncounter, this);
      this.encounterUi?.destroy(); this.encounterUi = undefined;
      this.sense?.clearIntel();
      this.sectTrial?.destroy(); this.prog.endTrialSkills();
      this.talismanUse?.interrupt('map');
      if (this.scene.isActive('talisman-craft-ui')) this.scene.stop('talisman-craft-ui');
      this.clearTalismanFx();
    });
    this.applyFeatureFlags();
    this.rememberPosition(this.map.id, this.player.x, this.player.y);
    if (featureEnabled('talismanCraft')) this.rememberMapVisited();
    if (featureEnabled('talismanCraft') && data.talismanReturnLand && data.map === this.map.id
      && data.pos?.x === this.player.x && data.pos?.y === this.player.y)
      this.createTalismanFx('fx_talisman_return_land', 'land', this.player.x, this.player.y, true);
    const returned = this.registry.get('sectTrialReturnMessage');
    const returnDetail = this.registry.get('sectTrialReturnDetail');
    this.registry.remove('sectTrialReturnMessage');
    this.registry.remove('sectTrialReturnDetail');
    if (returned || interrupted) this.log(returned ?? t('trial.exit_return'), '#ffe680');
    if (returnDetail) this.log(returnDetail, '#ffb0b0');
    this.setupEncounters();
    notifyCheatSceneReady(this);
  }

  /** 已接取本宗任务且尚未通关，才可由交付长老开启试炼。 */
  private sectTrialOfferFor(npcId: string, questId?: string): TrialDef | undefined {
    if (!featureEnabled('fiveSectClasses') || !featureEnabled('v05Maps') || this.prog.job || this.prog.pendingSectTrial) return;
    return Object.values(TRIALS).find(tr => {
      const q = tr.quest ? QUESTS_REF[tr.quest] : undefined;
      return q && (!questId || q.id === questId) && q.turnIn === npcId && this.quests.activeIds.includes(q.id)
        && !this.quests.sectEntryBlock(q.id)
        && !this.prog.completedTrials.includes(tr.id) && TILED_MAPS[tr.map] && mapEntryOpen(tr.map, this.map.id);
    });
  }

  offerSectTrial(npcId: string, def: TrialDef) {
    if (this.sectTrialOfferFor(npcId, def.quest)?.id !== def.id) return;
    const npc = NPCS[npcId];
    this.player.body.setVelocityX(0);
    this.dialog.choose({ speaker: npc.name, text: `${t('trial.enter_confirm')}\n${def.name}` }, npc.sprite, [
      { label: '进入试炼', onSelect: () => this.enterSectTrial(npcId, def) },
      { label: t('ui.dialog.close'), onSelect: () => {} },
    ]);
  }

  enterSectTrial(npcId: string, def: TrialDef): boolean {
    if (this.travelling || this.sectTrialOfferFor(npcId, def.quest)?.id !== def.id) return false;
    const mapId = sectEntryMap(NPCS[npcId].map);
    // 正常从山门长老旁返回；旧试炼图入口或调试入口也必须使用目标山门的坐标。
    const localElder = this.map.id === mapId
      ? this.map.objects.find(o => o.type === 'npc' && (o.props.npc ?? o.name) === npcId) : undefined;
    type TiledNpc = {
      type?: string; class?: string; name: string; x: number; y: number; properties?: { name: string; value: unknown }[];
    };
    const at = localElder ?? TILED_MAPS[mapId]?.layers.flatMap((layer: { objects?: TiledNpc[] }) => layer.objects ?? [])
      .find((o: TiledNpc) => (o.type || o.class) === 'npc'
      && (o.properties?.find(p => p.name === 'npc')?.value ?? o.name) === npcId);
    if (!at) return false;
    const returnPosition = { mapId, x: at.x, y: at.y };
    this.prog.pendingSectTrial = { id: def.id, returnPosition };
    this.prog.persistSoon();
    this.travelling = true;
    this.registry.set('sectTrialEntering', true);
    this.player.body.setVelocityX(0);
    this.scene.restart({ map: def.map });
    return true;
  }

  onSectTrialEnd(result: 'win' | 'fail' | 'exit', failureHint?: string) {
    const attempt = this.prog.pendingSectTrial;
    if (!attempt) return;
    const won = result === 'win' && this.quests.onTrialComplete(attempt.id);
    this.prog.pendingSectTrial = null;
    this.player.body.setVelocity(0, 0);
    for (const mob of this.mobs) if (mob.active && !mob.dead) mob.despawn();
    this.prog.endTrialSkills();
    this.prog.hp = this.prog.maxHp; this.prog.mp = this.prog.maxMp;
    const at = sectTrialReturnPosition(attempt.returnPosition);
    this.rememberPosition(at.mapId, at.x, at.y);
    const trial = TRIALS[attempt.id];
    this.registry.set('sectTrialReturnMessage', won ? `${sectTrialText(`trial.sect_${trial?.sect}_success`, '试炼已成！')}找长老交付入门任务即可拜入。`
      : t(result === 'fail' ? 'trial.fail_return' : 'trial.exit_return'));
    this.registry.set('sectTrialReturnDetail', result === 'fail' ? failureHint ?? '' : '');
    this.travelling = true;
    this.time.delayedCall(0, () => this.scene.restart({ map: at.mapId, pos: { x: at.x, y: at.y } }));
  }

  // ---------------- 筑基台试炼 ----------------
  trial?: AltarTrial;
  bossOverride: { name: string; hp: number; max: number } | null = null;

  private setupTrial(mapId: string) {
    const def = TRIAL_BY_MAP[mapId];
    const pending = this.registry.get('trialPending');
    if (def && (pending === def.id || (DEBUG_TRIAL && !this.registry.get('debugTrialUsed')))) {
      this.registry.set('trialPending', null); this.registry.set('debugTrialUsed', true);
      if (!this.registry.get('trialRate')) this.registry.set('trialRate', this.prog.breakthroughRate(false));
      const speed = Math.max(0.1, Number(QS.get('speed') ?? 1) || 1);
      this.trial = new AltarTrial(this, def, DEBUG_TRIAL ? speed : 1);
      this.log(t('trial.countdown', { sec: Math.round(def.durationMs / 1000) }), '#ffe680');
      const skip = DEBUG_TRIAL ? QS.get('skip') : null;
      if (skip === 'held' || skip === 'broken' || skip === 'dead') this.time.delayedCall(500, () => this.trial?.end(skip));
      return;
    }
    if (DEBUG_TRIAL && !def && !this.registry.get('debugTrialUsed')) {
      // 直接准备一个 29 级瓶颈、带筑基丹、考核已完成的角色
      const tr = Object.values(TRIALS).find(x => x.type === 'defend');
      const realm = REALMS.find((r: any) => r.trial === tr?.id);
      if (!tr || !realm) return;
      const pr = this.prog;
      pr.level = realm.levelMax; pr.exp = pr.expNeed;
      if (realm.breakthroughItem && pr.count(realm.breakthroughItem) < 1) pr.addItem(realm.breakthroughItem, 1);
      if (realm.breakthroughQuest) pr.quests[realm.breakthroughQuest] = { state: 'done', kills: {} };
      pr.hp = pr.maxHp; pr.mp = pr.maxMp;
      this.time.delayedCall(50, () => this.enterTrial(tr));
    }
  }

  /** 生成一只试炼怪（respawnMs 0，打死就消失） */
  spawnTrialMob(id: string, x: number, y: number) {
    const def = MONSTERS[id];
    if (!def) return null;
    const m = new Monster(this, x, y, def);
    m.noRespawn = true;
    this.wireMob(m);
    this.mobs.push(m);
    return m;
  }

  /** 和长老对话时：考核已完成、正卡在该境界瓶颈 → 可进试炼 */
  private trialOfferFor(npcId: string): TrialDef | null {
    const realm = this.prog.realm;
    if (!realm?.trial || !this.prog.atBreakthrough) return null;
    const qid = realm.breakthroughQuest, q = qid ? QUESTS_REF[qid] : null;
    if (!q || q.giver !== npcId || this.quests.state(qid) !== 'done') return null;
    const tr = TRIALS[realm.trial];
    return tr && tr.type === 'defend' && TILED_MAPS[tr.map] && mapEntryOpen(tr.map, this.map.id) ? tr : null;
  }

  offerTrial(npcId: string, tr: TrialDef) {
    if (!mapEntryOpen(tr.map, this.map.id)) {
      this.log(FEATURE_UNAVAILABLE, '#aaaaaa');
      const npc = NPCS[npcId];
      this.dialog.show([{ speaker: npc?.name ?? null, text: FEATURE_UNAVAILABLE }], npc?.sprite ?? null); return;
    }
    const npc = NPCS[npcId], realm = this.prog.realm, item = realm.breakthroughItem as string | null;
    const speaker = npc?.name ?? npcId;
    if (item && this.prog.count(item) < 1) {
      this.dialog.show([{ speaker, text: t('trial.need_pill', { item: ITEMS[item]?.name ?? item }) }], npc?.sprite ?? null);
      return;
    }
    const r = this.prog.breakthroughRate(undefined, item ? this.prog.pillQuality(item) : 'low');
    const pct = (v: number) => Math.round(v * 100);
    const lines = [
      { speaker, text: npc?.dialog?.[1] ?? '' },
      { speaker: null, text: t('realm.rate_detail', { rate: pct(r.rate), base: pct(r.base), pill: pct(r.pill), insight: pct(r.insight), clear: pct(r.clear), pity: pct(r.pity) }) },
      { speaker, text: t('trial.enter_hint', { sec: Math.round(tr.durationMs / 1000) }) },
    ].filter(l => l.text);
    this.dialog.show(lines, npc?.sprite ?? null, () => this.enterTrial(tr));
  }

  /** 进试炼：消耗突破丹药（和清心丹），记下本次成功率，载入试炼图 */
  enterTrial(tr: TrialDef) {
    if (!mapEntryOpen(tr.map, this.map.id)) { this.log(FEATURE_UNAVAILABLE, '#aaaaaa'); return; }
    const pr = this.prog, item = pr.realm.breakthroughItem as string | null;
    // 对话结束才入台；期间丹药可能已移走，缺丹时不能扣清心丹或切图。
    if (item && pr.count(item) < 1) {
      this.log(t('trial.need_pill', { item: ITEMS[item]?.name ?? item }), '#ffb0b0'); return;
    }
    const itemConsumed = !!item && pr.count(item) > 0;
    const withClear = pr.count('clear_mind_pill') > 0;
    const itemQuality = item ? pr.pillQuality(item) : 'low', clearQuality = pr.pillQuality('clear_mind_pill');
    const rate = pr.breakthroughRate(withClear, itemQuality);
    if (item) { pr.removeItem(item, 1); this.log(t('trial.consume', { item: ITEMS[item]?.name ?? item }), '#c8c8c8'); }
    if (withClear) { pr.removeItem('clear_mind_pill', 1); this.log(t('trial.consume', { item: ITEMS.clear_mind_pill?.name ?? '清心丹' }), '#c8c8c8'); }
    pr.hp = pr.maxHp; pr.mp = pr.maxMp; pr.persistSoon();
    this.registry.set('trialPending', tr.id); this.registry.set('trialRate', rate);
    this.cameras.main.fadeOut(200);
    this.time.delayedCall(220, () => {
      if (!mapEntryOpen(tr.map, this.map.id)) {
        if (item && itemConsumed) pr.addCraftedPill(item, 1, itemQuality);
        if (withClear) pr.addCraftedPill('clear_mind_pill', 1, clearQuality);
        pr.persistSoon(); this.registry.remove('trialPending'); this.registry.remove('trialRate');
        this.cameras.main.fadeIn(100); this.log(FEATURE_UNAVAILABLE, '#aaaaaa'); return;
      }
      this.scene.restart({ map: tr.map });
    });
  }

  /** 试炼结束：守不住只扣丹药（进场时已扣）；守住了按成功率掷骰 */
  onTrialEnd(result: TrialResult) {
    const pr = this.prog, p = this.player;
    const realm = pr.realm, pen = realm.failPenalty ?? {};
    const banner = (text: string, color = '#fff6c8') => {
      const tx = this.add.text(640, 250, text, { fontFamily: 'serif', fontSize: '40px', color, stroke: '#3b2a20', strokeThickness: 6,
        align: 'center', wordWrap: { width: 1120, useAdvancedWrap: true } }).setOrigin(0.5).setScrollFactor(0).setDepth(170);
      this.tweens.add({ targets: tx, alpha: { from: 0, to: 1 }, duration: 400, hold: 1600, yoyo: true, onComplete: () => tx.destroy() });
    };
    this.registry.set('lastTrialResult', null);
    if (result !== 'held') {
      const msg = result === 'broken' ? t('trial.altar_broken') : t('trial.player_down');
      this.log(msg, '#ff8080'); banner(msg, '#ffb0b0');
      this.log('丹药已在入台时消耗，修为没有损失，突破保底不变。备好丹药后可再次入台。', '#ffe680');
      this.registry.set('lastTrialResult', result);
      this.time.delayedCall(2600, () => this.returnFromTrial());
      return;
    }
    this.log(t('trial.success'), '#ffe680'); banner(t('trial.success'));
    const rate = (this.registry.get('trialRate') as { rate: number } | undefined)?.rate ?? pr.breakthroughRate(false).rate;
    const forced = DEBUG_TRIAL ? QS.get('roll') : null;
    const win = forced === 'win' ? true : forced === 'lose' ? false : Math.random() < rate;
    this.time.delayedCall(2200, () => {
      if (win) {
        const next = REALMS[REALMS.indexOf(realm) + 1];
        this.playCue('breakthrough', () => {
          const hadSwordRide = (pr.skills.sword_ride ?? 0) > 0;
          pr.breakthrough(); pr.breakthroughFails = 0; pr.unstableUntil = 0;
          pr.hp = pr.maxHp; pr.mp = pr.maxMp;
          this.player.maxHp = pr.maxHp; this.player.hp = pr.hp;
          this.log(`突破成功，当前境界 ${pr.realmName}`, '#ffb0ff');
          if (!hadSwordRide && (pr.skills.sword_ride ?? 0) > 0) this.log(t('fly.skill_granted'), '#bfefff');
          if (pr.lastOverflowReturned > 0) this.log(`溢出修为返还 ${pr.lastOverflowReturned}`, '#c8c8c8');
          this.registry.set('lastTrialResult', 'win');
          pr.persistSoon();
          this.time.delayedCall(1200, () => this.returnFromTrial());
        }, t('realm.breakthrough_ok', { realm: next?.name ?? '' }));
      } else {
        this.playBreakthroughFail(p.x, p.y);
        this.cameras.main.shake(300, 0.008);
        const gray = this.add.rectangle(640, 360, 1280, 720, 0x6a6a6a, 0).setScrollFactor(0).setDepth(149);
        this.tweens.add({ targets: gray, fillAlpha: 0.45, duration: 400 });
        const lost = pr.applyBreakthroughFail(Number(pen.expLossRatio ?? 0));
        pr.breakthroughFails++;
        if (pen.debuffMs) { pr.unstableUntil = gameNow() + Number(pen.debuffMs); pr.unstableRatio = Number(pen.debuffStatRatio ?? 0); pr.unstableStats = Array.isArray(pen.debuffStats) ? [...pen.debuffStats] : []; }
        const bonus = Math.round((BREAKTHROUGH.pityPerFail ?? 0) * 100);
        banner(t('realm.breakthrough_fail'), '#d0d0d0');
        this.log(t('realm.breakthrough_fail'), '#d0d0d0');
        this.log('阵眼已守住，但本次突破未成。丹药已在入台时消耗，修为圆满并备好丹药后可再次入台。', '#ffe680');
        this.log(t('realm.next_bonus', { bonus }), '#ffe680');
        if (lost.lost > 0) this.log(`修为 −${lost.lost}${lost.fromPool ? `（溢出池 −${lost.fromPool}）` : ''}`, '#c8c8c8');
        if (pen.debuffMs) this.log(t('realm.unstable', { min: Math.round(Number(pen.debuffMs) / 60000) }), '#ffb0b0');
        this.registry.set('lastTrialResult', 'lose');
        pr.persistSoon();
        this.time.delayedCall(3000, () => this.returnFromTrial());
      }
    });
  }

  private returnFromTrial() {
    const pr = this.prog;
    pr.hp = pr.maxHp; pr.mp = pr.maxMp; pr.persistSoon();
    this.registry.set('trialRate', null);
    this.cameras.main.fadeOut(250);
    this.time.delayedCall(270, () => this.scene.restart({ map: TRIAL_RETURN.map, pos: { x: TRIAL_RETURN.x, y: TRIAL_RETURN.y } }));
  }
  invText!: Phaser.GameObjects.Text;

  update(time: number, delta: number) {
    if (this.loadingProgress) return;
    // 塔内占位暂停山门模拟；清怪由门禁的可控接口驱动，退出不借长帧补结算。
    if (this.towerGate?.session) {
      const J = Phaser.Input.Keyboard.JustDown, k = this.keys;
      if (J(k.z) || J(k.up) || J(k.esc)) void this.exitTowerRoom();
      return;
    }
    // 单房占位期间不更新营地、战斗、任务、寿元或存档；只保留退出输入。
    if (this.secretNestRoom) {
      const J = Phaser.Input.Keyboard.JustDown, k = this.keys;
      if (J(k.z) || J(k.up) || J(k.esc)) this.exitSecretNestRoom();
      return;
    }
    const encounterOpen = this.encounterUi?.isOpen() === true;
    if (!encounterOpen && this.encounterOwnsPause) { this.physics.resume(); this.encounterOwnsPause = false; }
    const meditationInterrupted = ['left', 'right', 'up', 'down', 'space', 'alt', 'c', 'ctrl', 'x', 'i', 'e', 'k', 'l', 'p', 'r']
      .some(key => this.keys[key]?.isDown) || this.player.state2 === 'hurt' || this.player.dead;
    this.encounterRuntime?.update(delta > 1000 ? 0 : delta, { paused: this.scene.isPaused() || this.physics.world.isPaused
      || typeof document !== 'undefined' && document.hidden, interrupted: encounterOpen || meditationInterrupted || delta > 1000 });
    this.syncEncounterProps();
    if (encounterOpen || this.encounterUi?.isOpen()) {
      if (!this.physics.world.isPaused) { this.physics.pause(); this.encounterOwnsPause = true; }
      this.playerInput.clear(); this.playerPhysicsAccumulator = 0;
      const J = Phaser.Input.Keyboard.JustDown, k = this.keys;
      if (J(k.esc)) this.encounterUi?.clear();
      else {
        [k.one, k.two, k.three, k.four, k.five].forEach((key, i) => { if (J(key)) this.encounterUi?.selectChoice(i); });
        if (J(k.z) || J(k.space) || J(k.up)) this.encounterUi?.advance();
      }
      this.drawHud(); return;
    }
    this.sense?.tick();
    const senseKeyDown = this.senseUi?.update() ?? false;
    this.playerPhysicsAdvanced = false;
    try {
      this.updateFrame(time, delta, senseKeyDown);
    } finally {
      // Interactions and trial transitions can return before the normal movement point.
      if (!this.playerPhysicsAdvanced) this.advancePlayerPhysics(time, delta);
      this.player.refreshVisuals(time);
    }
  }

  private advancePlayerPhysics(time: number, delta: number, input?: Input) {
    this.playerPhysicsAdvanced = true;
    const neutral = !input || this.player.dead || !!this.sectTrial?.ended;
    if (neutral) this.playerInput.clear();
    else this.playerInput.capture(input);
    const world = this.physics.world;
    if (world.isPaused) {
      // Paused wall time must not become a burst of simulation when a panel closes.
      this.playerPhysicsAccumulator = 0;
      return;
    }
    this.playerPhysicsAccumulator += delta;
    while (this.playerPhysicsAccumulator + 1e-8 >= PLAYER_PHYSICS_MS) {
      this.playerPhysicsAccumulator = Math.max(0, this.playerPhysicsAccumulator - PLAYER_PHYSICS_MS);
      if (neutral) this.player.body.setVelocityX(0);
      // World.step() catch-up skips Body.preUpdate(), leaving contact flags from
      // the first tick. Separate updates reset them and sync Sprite positions.
      world.update(time, PLAYER_PHYSICS_MS);
      const stepped = world.stepsLastFrame > 0;
      world.postUpdate();
      if (stepped) {
        if (this.player.dead || this.sectTrial?.ended) this.playerInput.clear();
        // Keep all millisecond deadlines in the scene/render clock domain.
        this.player.step(time, PLAYER_PHYSICS_DT, this.playerInput.consume(), this.map.ropes);
      }
    }
  }

  private updateFrame(time: number, delta: number, senseKeyDown: boolean) {
    if (this.sectTrial?.ended) { this.drawHud(); return; }
    this.environmentArt?.update(delta);
    if (time >= this.nextDailyUpdateAt) {
      this.quests.refreshDaily(); this.nextDailyUpdateAt = time + 1000;
    }
    for (const { object, art } of this.portalVisuals)
      if (art instanceof Phaser.GameObjects.Sprite)
        this.playPropAnimation(art, this.portalOpen(object) ? 'prop_portal_open' : 'prop_portal_closed');
    this.player.syncAppearance();
    const k = this.keys, J = Phaser.Input.Keyboard.JustDown;
    this.clearAbandonedBossSummons();
    this.backgroundArt?.update(this.player, delta);
    for (const p of this.parallax) p.ts.tilePositionX = this.cameras.main.scrollX * p.f;
    this.updateShots(time);
    this.updateTalismanUse(delta);
    if (featureEnabled('talismanCraft')) {
      if (featureEnabled('indexedDbSaves')) void this.talismanSystem?.claimPendingAsync();
      else this.talismanSystem?.claimPending();
    }
    this.regenMp(delta);
    this.combat.update(time, delta);
    this.trialObjects?.update(delta);
    if (this.sectTrial && !this.sectTrial.ended && this.sectTrial.def.quest && this.quests.sectEntryBlock(this.sectTrial.def.quest)) {
      this.sectTrial.exit(); return;
    }
    if (this.sectTrial && !this.dialog.open && !this.skillWindow.open && !this.alchemy.isOpen() && !this.shop.isOpen() && !this.attrPanel?.isOpen() && !this.itemPanelOpen()) this.sectTrial.update(delta);
    if (this.sectTrial?.ended) { this.drawHud(); return; }
    if (time >= this.nextAgeUpdateAt) { this.prog.advanceAge(); this.nextAgeUpdateAt = time + 60000; this.prog.persistSoon(); }
    if (J(k.i)) { if (this.inventoryPanel?.isOpen()) this.inventoryPanel?.close(); else this.openInventoryPanel(); }
    if (J(k.e)) { if (this.equipPanel?.isOpen()) this.equipPanel?.close(); else this.openEquipPanel(); }
    if (J(k.k) && !this.dialog.open && !this.alchemy.isOpen() && !this.shop.isOpen() && !this.attrPanel?.isOpen() && !this.itemPanelOpen() && !this.sectTrial?.blocksInput) this.skillWindow.toggle();
    if (J(k.l) && !this.dialog.open && !this.skillWindow.open && !this.shop.isOpen() && !this.attrPanel?.isOpen() && !this.itemPanelOpen() && !this.sectTrial?.blocksInput) this.openAlchemy();
    if (J(k.p) && !this.itemPanelOpen()) {
      if (this.attrPanel?.isOpen()) this.attrPanel.close();
      else this.openAttrPanel();
    }
    const escDown = J(k.esc);
    if (escDown && this.skillWindow.open) this.skillWindow.close();
    if (escDown && this.attrPanel?.isOpen()) this.attrPanel.close();
    if (escDown) this.closeItemPanels();
    const modal = this.dialog.open || this.skillWindow.open || this.alchemy.isOpen() || this.shop.isOpen() || this.attrPanel?.isOpen() || this.itemPanelOpen() || !!this.sectTrial?.blocksInput;
    this.updateInteractionPrompts(modal);
    this.gathering.update(delta, k.z.isDown, modal || this.hasNearbyDrop(),
      k.left.isDown || k.right.isDown || k.up.isDown || k.down.isDown || k.space.isDown || k.alt.isDown || k.c.isDown || k.ctrl.isDown || k.x.isDown);
    if (modal) {
      this.alchemy.update(delta);
      this.shop?.update();
      this.attrPanel?.update();
      this.inventoryPanel?.update(); this.equipPanel?.update();
      if (this.dialog.open) {
        [k.one, k.two, k.three, k.four, k.five].forEach((key, i) => { if (J(key)) this.dialog.selectChoice(i); });
        if (escDown) this.dialog.dismissChoices();
      }
      if (this.dialog.open && (J(k.z) || J(k.space) || J(k.up))) this.dialog.advance();
      if (this.skillWindow.open) {
        const nums = [k.one, k.two, k.three, k.four, k.five];
        nums.forEach((key, i) => { if (J(key)) this.skillWindow.addPoint(i); });
      }
      J(k.alt); J(k.c);
      J(k.space); J(k.z); J(k.up); J(k.ctrl); J(k.x);
      this.advancePlayerPhysics(time, delta);
      this.stealth?.update(0, false);
      for (const m of this.mobs) {
        if (m.despawning) m.step(time, this.player);
        else if (m.def.isBoss) m.recoverInBounds();
      }
      this.drawHud(); return;
    }
    if (senseKeyDown) this.senseUi?.requestScan('key');
    this.trial?.update(delta);
    const jumpAlt = J(k.alt), jumpSpace = J(k.space), jumpC = J(k.c);
    const attackCtrl = J(k.ctrl), attackX = J(k.x);
    const inp: Input = {
      left: k.left.isDown, right: k.right.isDown, up: k.up.isDown, down: k.down.isDown,
      jumpDown: jumpAlt || jumpSpace || jumpC,
      attackDown: attackCtrl || attackX,
      attackHeld: k.ctrl.isDown || k.x.isDown,
    };
    if (J(k.f1)) this.toggleDebug();
    if (J(k.r)) {
      if (this.sectTrial) { this.sectTrial.exit(); return; }
      this.playerInput.clear();
      this.interruptTalisman('move'); this.player.leaveRope(time); this.player.body.reset(this.map.spawn.x, this.map.spawn.y);
    }
    if (J(k.one)) this.usePill('hp_pill_small');
    if (J(k.two)) this.usePill('qi_pill');
    if (J(k.z) && this.player.state2 === 'ground' && !this.gathering.active && !this.hasNearbyDrop()
      && (this.tryInteractTowerClosed() || this.tryInteractMarketConsign() || this.tryInteractForgeEntrance() || this.tryInteractSecretNest() || this.encounterRuntime?.interact() || this.interactTrialObject() || this.openNearbyFurnace() || this.talkNearby())) return;
    if (k.z.isDown && !this.gathering.active && time >= this.nextPickAt) { this.nextPickAt = time + 150; this.tryPickup(); }
    if (J(k.up) && this.player.state2 === 'ground' && this.tryInteract()) return;
    // ↑ + 既有跳跃键触发御剑冲刺；交互和绳上跳跃仍由原入口处理。
    if (inp.up && inp.jumpDown && this.player.state2 !== 'rope' && !this.gathering.active) {
      const direction = (inp.right ? 1 : 0) - (inp.left ? 1 : 0);
      if (direction) this.player.facing = direction;
      if (this.combat.trySwordRide()) inp.jumpDown = false;
    }
    const slotKey: Record<string, Phaser.Input.Keyboard.Key> = { A: k.a, S: k.s, D: k.d, F: k.f, G: k.g, H: k.h, Q: k.q, W: k.w };
    HOTBAR_SLOTS.forEach((s, i) => { if (J(slotKey[s.label]) && !this.gathering.active) {
      const talisman = featureEnabled('talismanCraft') ? this.prog.talismanQuickSlots[i] : null;
      if (talisman) {
        if (featureEnabled('indexedDbSaves')) void this.useTalismanAsync(talisman.item, talisman.quality);
        else this.useTalisman(talisman.item, talisman.quality);
      }
      else this.combat.tryCast(i);
    } });
    this.checkReach();
    if (this.player.y > this.map.height + 100) {
      this.interruptTalisman('move');
      if (this.sectTrial) { this.sectTrial.playerDown(); return; }
      this.playerInput.clear();
      this.player.body.reset(this.map.spawn.x, this.map.spawn.y);
    }

    this.advancePlayerPhysics(time, delta, inp);
    for (const m of this.mobs) m.step(time, this.player, this.prog.hasBuffEffect('invisible'));
    if (this.sectTrial?.ended) { this.drawHud(); return; }
    for (let i = this.mobs.length - 1; i >= 0; i--) if (!this.mobs[i].active) this.mobs.splice(i, 1);
    this.stealth?.update(delta, true);
    if (this.sectTrial?.ended) { this.drawHud(); return; }
    for (const d of this.drops.getChildren() as Drop[]) {
      if (!d.landed && d.shadow && (d.body as Phaser.Physics.Arcade.Body).blocked.down) this.landDrop(d);
      d.label?.setPosition(d.x, d.y - (d.shadow ? 34 : 22));
      if (time - d.bornAt > 60000) this.removeDrop(d);
    }
    const z = this.map.zones.find(z => this.player.x >= z.x && this.player.x <= z.x + z.w && this.player.y >= z.y && this.player.y <= z.y + z.h);
    if (z?.name !== this.curZone) {
      this.curZone = z?.name;
      const foxClosed = z?.props.unlockQuest === 'q_fox' && !featureEnabled('foxBoss');
      if (z?.props.label) this.log(foxClosed ? FEATURE_UNAVAILABLE : `进入 ${z.props.label}`, '#ffd0ff');
      const boss = this.mobs.find(m => m.def.isBoss && !m.dead && z && m.x >= z.x && m.x <= z.x + z.w);
      if (!foxClosed && boss && !this.bossIntroShown && z?.props.unlockQuest) { this.bossIntroShown = true; this.dialog.show(SCRIPTS[z.props.unlockQuest]?.bossIntro ?? [], null); }
    }
    // 独立检查教学区，重叠 zone 也能触发；对白空闲后才记入存档并弹出。
    if (!this.dialog.open) for (const tutorialZone of this.map.zones) {
      const id = tutorialZone.props.tutorial;
      if (typeof id !== 'string' || !id || this.player.x < tutorialZone.x || this.player.x > tutorialZone.x + tutorialZone.w
        || this.player.y < tutorialZone.y || this.player.y > tutorialZone.y + tutorialZone.h) continue;
      if (!this.prog.markTutorialSeen(id)) continue;
      const text = t(`tip.${id}`);
      this.log(text, '#ffe680');
