  parallax: { ts: Phaser.GameObjects.TileSprite; f: number }[] = [];
  dialog!: DialogBox;
  skillBar!: SkillBar;
  skillWindow!: SkillWindow;
  combat!: SkillCombat;

  /** 失效交互的拒绝钩子；关态不创建邀请按钮、关系或同行实体。 */
  requestCompanionInvite(companionId: string = SU_COMPANION_ID) {
    const result = invite(COMPANIONS, AFFINITY, this.prog, companionId);
    this.log(t(result.hintKey), '#d0d0d0');
    return result;
  }

  /** 本 tip 仅接拒绝钩子，无持续飞行输入或地图区域，尝试不会扣蓝。 */
  requestSustainFlight() {
    const result = requestSustainFlight(FLY_ZONES, {
      realmId: this.prog.realm.id, realmOrder: REALMS.map(realm => realm.id),
      ownsSkill: this.prog.skillLevel(FLY_ZONES?.skillId ?? 'sword_ride') > 0,
      mapId: this.map.id, inFlyZone: false, mp: this.prog.mp,
    });
    this.log(t(result.messageKey), '#d0d0d0');
    return result;
  }
  private mpPool = 0;
  tracker!: Phaser.GameObjects.Text;
  bossIntroShown = false;
  hudTexts?: Phaser.GameObjects.Text[];
  /** 当前地图上的首领（含已死、尚未重生的那只），测试从 window.__scene.boss 拿 */
  get boss(): Monster | null { return this.mobs.find(m => m.def.isBoss && !m.owner) ?? null; }
  gourd!: Phaser.GameObjects.Image;
  gourdTip!: Phaser.GameObjects.Text;
  bossName!: Phaser.GameObjects.Text;
  bossHpText!: Phaser.GameObjects.Text;
  private shots: Shot[] = [];
  private shotOf = new Map<Phaser.GameObjects.GameObject, Shot>();
  private shotGroup?: Phaser.Physics.Arcade.Group;

  // ---------------- 战斗 ----------------
  private wireMob(m: Monster) {
    m.onDead = mm => this.onMobDead(mm);
    m.onSlam = (mm, rect) => this.onSlam(mm, rect);
    m.onVolley = v => this.launchVolley(v);
    m.onSkillDamage = (mm, ratio, kb, fromX) => this.hurtPlayer(this.prog.damageFrom(mm.def.atk, ratio), fromX, kb);
    m.onSummon = (owner, id, x, y, grant, despawn) => this.spawnSummon(owner, id, x, y, grant, despawn);
  }

  private spawnSummon(owner: Monster, id: string, x: number, y: number, grantRewards: boolean, despawnWithOwner: boolean) {
    const def = MONSTERS[id];
    if (!def || !owner.active) return;
    if (!featureEnabled('foxBoss') && (id === 'demon_fox' || owner.def.id === 'demon_fox')) return;
    // 召唤阵延迟到第 4 帧才刷怪；败北或离区后仍让首领动作正常结束，但不补刷随主清场的召唤物。
    if (despawnWithOwner && this.bossSummonsShouldDespawn(owner)) return;
    const m = new Monster(this, x, y, def);
    m.owner = owner; m.grantRewards = grantRewards; m.despawnWithOwner = despawnWithOwner; m.noRespawn = true;
    this.wireMob(m);
    owner.summons.push(m);
    this.mobs.push(m);
  }

  private bossSummonsShouldDespawn(owner: Monster) {
    if (!owner.def.isBoss || owner.owner) return false;
    if (this.player.dead) return true;
    const zone = owner.arenaZone;
    return !!zone && (this.player.x < zone.x || this.player.x > zone.x + zone.w
      || this.player.y < zone.y || this.player.y > zone.y + zone.h);
  }

  private clearAbandonedBossSummons() {
    for (const m of this.mobs) if (this.bossSummonsShouldDespawn(m)) m.clearSummons();
  }

  private launchVolley(v: SkillVolley) {
    if (!this.shotGroup) {
      this.shotGroup = this.physics.add.group();
      this.physics.add.collider(this.shotGroup, this.map.solids, obj => { const s = this.shotOf.get(obj as Phaser.GameObjects.GameObject); if (s) this.impactShot(s, false); });
      this.physics.add.overlap(this.player, this.shotGroup, (_p, obj) => { const s = this.shotOf.get(obj as Phaser.GameObjects.GameObject); if (s) this.impactShot(s, true); });
    }
    const pack = this.cache.json.get(`${v.fx}_anims`);
    const anims = (pack?.anims ?? []) as { key: string; frames: string[]; frameRate: number }[];
    const fly = anims.find(a => a.key.includes('fly')) ?? anims[0];
    const hit = anims.find(a => a.key.includes('hit'));
    const origin = (pack?.origin ?? [0.5, 0.5]) as [number, number];
    const hitMs = hit ? hit.frames.length * (1000 / hit.frameRate) : 200;
    let tex = v.fx;
    if (!this.textures.exists(tex)) {
      if (!v.maxDist) return;
      // 没有弹道图集时：小黄色矩形占位（黑袍人的符）
      tex = 'ph_talisman';
      if (!this.textures.exists(tex)) { const g = this.make.graphics({}, false); g.fillStyle(0xf2d04a).fillRect(0, 0, 20, 12).lineStyle(2, 0x8a5a10).strokeRect(0, 0, 20, 12); g.generateTexture(tex, 20, 12); g.destroy(); }
    }
    for (const sh of v.shots) {
      const s = this.physics.add.sprite(sh.x, sh.y, tex);
      s.setOrigin(origin[0], origin[1]).setDepth(12).setBlendMode(Phaser.BlendModes.NORMAL).setFlipX(sh.vx > 0);
      this.shotGroup.add(s);   // 先进组：PhysicsGroup 加入时会把重力、速度重置成组默认值，所以之后再设
      const body = s.body as Phaser.Physics.Arcade.Body;
      const bw = v.body?.w ?? 22, bh = v.body?.h ?? 18;
      body.setAllowGravity(false).setSize(bw, bh).setOffset((s.width - bw) / 2, (s.height - bh) / 2).setVelocity(sh.vx, sh.vy);
      if (fly && this.anims.exists(fly.key)) s.play(fly.key);
      const shot: Shot = { sprite: s, state: 'fly', until: 0, ratio: v.ratio, kb: v.knockback, atk: v.atk, hitAnim: hit?.key, hitMs, fromX: sh.x, maxDist: v.maxDist };
      this.shots.push(shot); this.shotOf.set(s, shot);
    }
  }

  private impactShot(s: Shot, hitPlayer: boolean) {
    if (s.dead || !s.sprite.scene || !s.sprite.active || !s.sprite.body) { this.removeShot(s); return; }
    if (s.state !== 'fly') return;
    s.state = 'hit';
    const body = s.sprite.body as Phaser.Physics.Arcade.Body;
    body.setVelocity(0, 0); body.enable = false;
    if (hitPlayer) this.hurtPlayer(this.prog.damageFrom(s.atk, s.ratio), s.sprite.x, s.kb);
    if (s.hitAnim && this.anims.exists(s.hitAnim)) s.sprite.play(s.hitAnim);
    s.until = this.time.now + s.hitMs;
  }

  private updateShots(time: number) {
    for (const s of this.shots) {
      if (s.dead || !s.sprite.scene || !s.sprite.active || !s.sprite.body) { this.removeShot(s); continue; }
      const gone = s.state === 'hit' ? time >= s.until
        : (s.maxDist && Math.abs(s.sprite.x - (s.fromX ?? s.sprite.x)) >= s.maxDist) ? (this.impactShot(s, false), false)
        : s.sprite.x < -80 || s.sprite.x > this.map.width + 80 || s.sprite.y < -120 || s.sprite.y > this.map.height + 120;
      if (!gone) continue;
      this.removeShot(s);
    }
    if (this.shots.some(s => s.dead)) this.shots = this.shots.filter(s => !s.dead);
  }

  doAttack(rect: Phaser.Geom.Rectangle) {
    this.interruptTalisman('attack');
    if (this.sectTrial?.ended) return;
    const p = this.player, s = p.facing;
    if (this.anims.exists('fx_sword_slash_play')) {      // 刀光：第 2 帧播放，普通混合（加色在白云背景上看不见）
      const fx = this.add.sprite(p.x + s * 36, p.y + 10, 'fx_sword_slash').setOrigin(0.5, 1).setDepth(12).setFlipX(s > 0);
      fx.play('fx_sword_slash_play'); fx.once(Phaser.Animations.Events.ANIMATION_COMPLETE, () => fx.destroy());
    } else {
      const fx = this.add.graphics().setDepth(12);
      fx.lineStyle(6, 0xbfefff, 0.9);
      fx.beginPath(); fx.arc(p.x, p.y - SPEC.bodyH / 2, FEEL.attackRange - 8, s > 0 ? -1.2 : Math.PI - 1.0, s > 0 ? 1.0 : Math.PI + 1.2); fx.strokePath();
      this.tweens.add({ targets: fx, alpha: 0, duration: 200, onComplete: () => fx.destroy() });
    }

    let best: Monster | null = null, bestD = Infinity;   // 普攻只打最近的一只
    for (const m of this.mobs) {
      if (m.dead) continue;
      const mb = m.body;
      if (!Phaser.Geom.Intersects.RectangleToRectangle(rect, new Phaser.Geom.Rectangle(mb.x, mb.y, mb.width, mb.height))) continue;
      const d = Math.abs(m.x - p.x);
      if (d < bestD) { bestD = d; best = m; }
    }
    if (!best) return;
    const dmg = this.prog.damageTo(best.def.level, best.def.def);
    best.takeHit(this.time.now, dmg, s);
    this.damageNumber(best.x, best.y - best.body.height - 10, dmg, '#ffb02e', '#6b2a00');
  }

  onSlam(m: Monster, rect: Phaser.Geom.Rectangle) {
    const fx = this.add.rectangle(rect.centerX, rect.centerY, rect.width, rect.height, 0xff7a3a, 0.35).setDepth(9);
    this.tweens.add({ targets: fx, alpha: 0, duration: 300, onComplete: () => fx.destroy() });
    this.cameras.main.shake(120, 0.004);
    const pb = this.player.body;
    if (Phaser.Geom.Intersects.RectangleToRectangle(rect, new Phaser.Geom.Rectangle(pb.x, pb.y, pb.width, pb.height)))
      this.hurtPlayer(this.prog.damageFrom(m.def.atk, m.def.attack!.damageRatio), m.x, m.def.attack!.knockback);
  }

  hurtPlayer(dmg: number, fromX: number, knock: number) {
    if (this.sectTrial?.ended || this.player.dead || this.time.now < this.player.invulnUntil) return;
    if (Math.random() < this.prog.passiveBonus('evade')) return;
    const shield = Math.min(1, Math.max(0, this.prog.buffBonus('damageToMpRatio')));
    const mpPerDamage = this.prog.buffBonus('mpPerAbsorbedDamage') || 1;
    const absorbed = Math.min(Math.floor(dmg * shield), Math.floor(this.prog.mp / mpPerDamage));
    dmg = Math.max(0, dmg - absorbed);
    if (!this.player.hurt(this.time.now, fromX, dmg, knock)) return;
    this.prog.mp = Math.max(0, this.prog.mp - absorbed * mpPerDamage);
    this.gathering.cancel();
    this.encounterRuntime?.interrupt();
    this.interruptTalisman('damage');
    this.prog.hp = Math.max(0, this.prog.hp - dmg);
    this.player.hp = this.prog.hp;
    this.damageNumber(this.player.x, this.player.y - 70, dmg, '#c45cff', '#2a0040');
    if (this.prog.hp <= 0) this.playerDie();
  }

  playerDie() {
    this.encounterRuntime?.terminate('failed');
    this.talismanUse?.onDeath();
    const p = this.player;
    p.dead = true; p.state2 = 'hurt'; p.hurtUntil = Infinity;
    this.clearAbandonedBossSummons();
    if (p.atlas) p.play(p.animationKey('die'));
    if (this.trial && !this.trial.ended) { this.trial.end('dead'); return; }
    if (this.trial) return;
    if (this.sectTrial) { this.sectTrial.playerDown(); return; }
    if (this.map.trial) {
      this.events.emit('trial:object', { trial: this.map.trial, action: 'player_down' });
      this.time.delayedCall(1000, () => {
        this.prog.hp = this.prog.maxHp; this.prog.mp = this.prog.maxMp;
        this.scene.restart({ map: this.map.id });
      });
      return;
    }
    this.log('你被击倒了，3 秒后在出生点复活', '#ff8080');
    this.time.delayedCall(3000, () => {
      this.prog.hp = this.prog.maxHp; this.prog.mp = this.prog.maxMp;
      p.dead = false; p.hp = this.prog.hp; p.hurtUntil = 0; p.state2 = 'air'; p.invulnUntil = this.time.now + 2000;
      p.body.reset(this.map.spawn.x, this.map.spawn.y);
    });
  }

  onMobDead(m: Monster) {
    this.sense?.removeMonsterIntel(m);
    // grantRewards 默认 false 的召唤物：不给修为、不掉落、不计任务击杀，也不进任何击杀统计
    if (!m.grantRewards) return;
    const d = m.def;
    this.quests.onKill(d.id);
    if (d.isBoss) this.time.delayedCall(600, () => {
      if (d.id !== 'demon_fox' || featureEnabled('foxBoss')) {
        this.attrPanel?.close();
        this.closeItemPanels();
        this.dialog.show(SCRIPTS.q_fox?.bossDeath ?? [], null);
      }
    });
    if (d.exp > 0) this.applyExp(this.prog.gainExp(d.exp, d.level));
    const t = d.dropTable ? DROPS[d.dropTable] : null;
    if (!t) return;
    const out: [string, number][] = [];
    const [lo, hi] = t.spiritStone ?? [0, 0];
    if (hi > 0) out.push(['spirit_stone', Phaser.Math.Between(lo, hi)]);
    for (const it of t.items) if (Math.random() < it.chance) out.push([it.item, Phaser.Math.Between(it.count[0], it.count[1])]);
    out.forEach(([id, n], i) => this.spawnDrop(m.x + (i - (out.length - 1) / 2) * 22, m.y - 20, id, n));
  }

  // ---------------- 掉落与拾取 ----------------
  private hasNearbyDrop() {
    return (this.drops.getChildren() as Drop[]).some(d => d.active
      && Math.abs(d.x - this.player.x) < 40 && Math.abs(d.y - this.player.y) < 40);
  }

  private updateInteractionPrompts(blocked: boolean) {
    for (const { object: o, prompt, marker } of this.interactionPrompts) {
      const furnace = o.type === 'furnace' || o.type === 'alchemy';
      if (o.type === 'npc' && (o.props.npc ?? o.name) === 'doctor_sun') {
        const label = prompt.list[prompt.list.length - 1] as Phaser.GameObjects.Text;
        const text = featureEnabled('alchemyPhase1') ? '对话 / L 炼丹' : '对话';
        if (label.text !== text) {
          label.setText(text);
          prompt.setX(o.x - ((hudSpec(this, 'ui_hud_keycap')?.size?.[0] ?? 20) + 4 + label.width) / 2);
        }
      }
      if (marker) {
        const marked = !!this.quests.mark(o.props.npc ?? o.name);
        const capHeight = hudSpec(this, 'ui_hud_keycap')?.size?.[1] ?? 20;
        prompt.setY(marked ? o.y + marker.y - marker.displayHeight - capHeight - 4 : o.y - 52);
      }
      prompt.setVisible((!furnace || featureEnabled('alchemyPhase1')) && !blocked && !this.player.dead && !this.hasNearbyDrop()
        && Math.abs(o.x - this.player.x) < 40 && Math.abs(o.y - this.player.y) < 48);
    }
  }

  private inTalismanCombat() {
    return this.player.dead || this.player.state2 === 'hurt' || this.time.now < this.player.attackLockUntil
      || this.mobs.some(mob => !mob.dead && (mob.st === 'chase' || mob.st === 'attack' || mob.st === 'hit'));
  }

  /** 后续打坐、模态窗口和生活技能须登记真实 busy 状态；不注册扫描按键。 */
  registerSenseBusy(check: () => boolean): () => void {
    this.senseBusyProviders.add(check);
    return () => this.senseBusyProviders.delete(check);
  }

  private senseBusy(): boolean {
    return this.travelling || this.senseCueDepth > 0 || !!this.encounterUi?.isOpen() || !!this.dialog?.open || !!this.skillWindow?.open
      || !!this.alchemy?.isOpen() || !!this.shop?.isOpen() || !!this.attrPanel?.isOpen() || this.itemPanelOpen()
      || !!this.gathering?.active || !!this.player?.gathering || !!this.alchemySystem?.active || !!this.talismanSystem?.active
      || !!this.talismanUse?.cast || this.scene.isActive('talisman-craft-ui') || this.scene.isPaused()
      || this.physics.world.isPaused || !!this.sectTrial?.blocksInput || !!this.sectTrial?.ended || !!this.trial?.ended
      || [...this.senseBusyProviders].some(check => check());
  }

  /** 持续打坐系统尚未开放；仅由真实系统注册，不从坐姿动画推断状态。 */
  registerEncounterMeditation(provider: EncounterMeditationProvider): () => void {
    return this.encounterRuntime?.registerMeditation(provider) ?? (() => {});
  }

  private setupEncounters(config: EncountersConfig | null = ENCOUNTERS) {
    this.encounterConfig = config;
    this.encounterProps ??= new Map();
    this.encounterRuntime = new EncounterSceneRuntime({ progress: this.prog, config, pacing: pacing.encounter,
      battle: createEncounterBattleProvider<Monster>({
        fallbackAnchor: () => ({ x: this.player.x, y: this.player.feet }),
        schedule: (delayMs, callback) => {
          const timer = this.time.delayedCall(delayMs, callback);
          return { dispose: () => timer.remove(false) };
        },
        warn: point => {
          const x = Phaser.Math.Clamp(point.x, 32, this.map.width - 32);
          const mark = this.add.ellipse(x, point.y - 4, 58, 14, 0x8f5b25, 0.3).setStrokeStyle(2, 0xe7c86a).setDepth(7);
          return { dispose: () => mark.destroy() };
        },
        spawn: (id, x, y) => this.spawnTrialMob(id, Phaser.Math.Clamp(x, 32, this.map.width - 32), y),
        onDeath: (mob, callback) => {
          const previous = mob.onDead;
          const listener = (dead: Monster) => { previous?.(dead); callback(); };
          mob.onDead = listener;
          return { dispose: () => { if (mob.onDead === listener) mob.onDead = previous; } };
        },
        destroy: mob => {
          mob.retire();
          // Phaser 的 collider/overlap 持有同一数组，必须原位移除，且不能同步毁掉正在 step 的 body。
          const index = this.mobs.indexOf(mob);
          if (index >= 0) this.mobs.splice(index, 1);
        },
      }),
      context: () => ({ mapId: this.map.id, level: this.prog.level, realmId: this.prog.realm.id,
        questsDone: this.prog.quests, sectJoined: !!this.prog.sect, daoHeart: this.prog.daoHeart, nowMs: gameNow(),
        luck: 0, blocked: this.encounterBlocked(),
        featuresReady: { moral_state: Number.isSafeInteger(this.prog.daoHeart) && Number.isSafeInteger(this.prog.morality),
          insight_reward: true, spirit_scan: featureEnabled('spiritScan') } }),
      anchor: definition => {
        const object = this.encounterAnchor(definition);
        const sprite = object && this.encounterProps.get(object)?.sprite;
        return object ? { x: object.x, y: object.y, height: sprite?.displayHeight ?? object.h } : undefined;
      },
      near: target => Math.abs(target.x - this.player.x) <= 40 && Math.abs(target.y - this.player.feet) <= 48,
      emit: (name, payload) => this.events.emit(name, payload ? { ...payload, vars: { ...payload.vars, player: this.prog.name } } : undefined),
      onCommit: () => {
        this.player.maxHp = this.prog.maxHp; this.player.hp = this.prog.hp; this.player.syncAppearance();
        this.syncEncounterProps();
      },
    });
    this.unregisterEncounterSense?.();
    // fixture / 局部桥接可不构造 Sense；正式 create 路径 setupSense 在前。
    if (this.sense?.registerAdapter) {
      this.unregisterEncounterSense = this.sense.registerAdapter('encounter', { targets: () => this.encounterSenseTargets() });
    }
    this.events.on('encounter:ui-advance', this.advanceEncounter, this);
    this.events.on('encounter:ui-choice', this.chooseEncounter, this);
    this.events.on('encounter:ui-puzzle', this.puzzleEncounter, this);
    // 同地图刷新沿已保存 visit；真正跨图才生成新 visit，不依赖随机数。
    const visit = this.prog.encounters?.visit as { id?: string; map?: string } | undefined;
    const sequence = Number(this.registry.get('encounterVisitSequence') ?? 0) + 1;
    this.registry.set('encounterVisitSequence', sequence);
    this.encounterRuntime.enter(visit?.map === this.map.id && visit.id ? visit.id : `${this.map.id}:${gameNow()}:${sequence}`);
    this.syncEncounterProps();
  }

  private encounterAnchor(definition: EncounterDefinition): MapObj | undefined {
    return this.map.objects.find(row => row.name === definition.trigger.anchor
      && (row.type === 'encounter_anchor' || row.type === 'hidden') && row.props.encounter === definition.id);
  }

  private currentEncounter() {
    if (!this.encounterRuntime) return;
    const active = this.prog.encounters?.active as EncounterActive | null | undefined;
    if (!active || typeof active !== 'object' || Array.isArray(active)
      || typeof active.attemptId !== 'string' || !active.attemptId
      || !active.locals || typeof active.locals !== 'object' || Array.isArray(active.locals)) return;
    const definition = active && this.encounterConfig?.encounters.find(row => row.enabled && row.id === active.encounterId);
    if (!definition || active.parentMap !== this.map.id || !definition.maps.includes(this.map.id)
      || !definition.script.steps.some(step => step.id === active.stepId) || typeof active.costApplied !== 'boolean') return;
    const object = this.encounterAnchor(definition);
    if (object) return { active, definition, object };
  }

  /** 只构建当前已抽中的真实锚点；关态与缺锚点都不分配图元。 */
  private syncEncounterProps() {
    this.encounterProps ??= new Map();
    const current = this.currentEncounter();
    for (const [object, prop] of this.encounterProps) {
      if (object !== current?.object || prop.attemptId !== current.active.attemptId) {
        prop.sprite.destroy(); this.encounterProps.delete(object);
      }
    }
    if (!current) return;
    const { active, definition, object } = current;
    const revealed = definition.trigger.reveal !== 'spirit_scan' || active.locals.revealed === true;
    const visual = resolveEncounterProp(object, this.encounterConfig, { active: true, revealed });
    if (!visual) return;
    let prop = this.encounterProps.get(object);
    if (!prop) {
      const sprite = createEncounterProp(this, object, visual);
      if (!sprite) return;
      prop = { sprite, visual, attemptId: active.attemptId, revealed };
      this.encounterProps.set(object, prop);
    } else {
      if (revealed && !prop.revealed) revealEncounterProp(this, prop.sprite, visual, { fx: true });
      else playEncounterProp(this, prop.sprite, visual);
      prop.revealed = revealed; prop.visual = visual;
    }
    prop.sprite.setVisible(visual.visible);
  }

  private encounterSenseTargets(): SenseTarget[] {
    const current = this.currentEncounter();
    if (!current || this.encounterBlocked() || current.definition.trigger.reveal !== 'spirit_scan'
      || current.active.locals.revealed === true) return [];
    const { active, definition, object } = current;
    const requirement = object.props.reqSpirit ?? definition.trigger.reqSpirit ?? 0;
    const reqSpirit = typeof requirement === 'number' && Number.isFinite(requirement) && requirement >= 0 ? requirement : NaN;
    return [{ kind: 'entrance', instanceId: this.map.id, id: object.name,
      x: object.x, y: object.y, reqSpirit, active: true, persistence: 'adapter',
      revealed: () => this.currentEncounter()?.active.attemptId === active.attemptId
        && this.currentEncounter()?.active.locals.revealed === true,
      stageReveal: () => {
        const latest = this.currentEncounter();
        if (!latest || this.encounterBlocked() || latest.active.attemptId !== active.attemptId || latest.object !== object
          || latest.definition.trigger.reveal !== 'spirit_scan') throw new Error('stale_encounter_anchor');
        // 仅暂存 runner.reveal 所属的两个字段，随 Sense.save 一起写盘；失败恢复原引用。
        // 不能在 stage 调 runner.reveal：其待保存事务会在扫描扣费失败后被自动重试。
        const previous = this.prog.encounters;
        const staged = structuredClone(previous!) as Record<string, unknown>;
        const stagedActive = staged.active as EncounterActive;
        stagedActive.locals.revealed = true;
        const seen = staged.seen;
        if (seen !== undefined && (!Array.isArray(seen) || !seen.every(id => typeof id === 'string'))) throw new Error('invalid_encounter_seen');
        staged.seen = [...new Set([...(seen ?? []), active.encounterId])];
        this.prog.encounters = staged;
        return () => { this.prog.encounters = previous; };
      },
      applyReveal: () => { this.encounterRuntime?.reveal(active.attemptId); this.syncEncounterProps(); },
    }];
  }

  private advanceEncounter(payload: Parameters<EncounterSceneRuntime['advance']>[0]) { this.encounterRuntime?.advance(payload); }
  private chooseEncounter(payload: Parameters<EncounterSceneRuntime['choose']>[0]) { this.encounterRuntime?.choose(payload); }
  private puzzleEncounter(payload: Parameters<EncounterSceneRuntime['puzzle']>[0]) { this.encounterRuntime?.puzzle(payload); }

  private encounterBlocked(): boolean {
    const p = this.player;
    return !p || p.dead || this.travelling || this.senseCueDepth > 0 || this.dialog.open || this.skillWindow.open
      || this.alchemy.isOpen() || this.shop.isOpen() || this.attrPanel.isOpen() || this.itemPanelOpen()
      || !!this.trial || !!this.sectTrial || !!this.map.trial || !!TRIAL_BY_MAP[this.map.id]
      || this.gathering.active || p.gathering || this.inTalismanCombat()
      || this.scene.isPaused() || this.physics.world.isPaused && !this.encounterOwnsPause
      || typeof document !== 'undefined' && document.hidden
      || this.map.objects.some(o => o.type === 'ferry' && Math.abs(o.x - p.x) < 64 && Math.abs(o.y - p.feet) < 64)
      || this.map.zones.some(zone => !!zone.props.unlockQuest && p.x >= zone.x && p.x <= zone.x + zone.w && p.y >= zone.y && p.y <= zone.y + zone.h);
  }

  private setupSense() {
    const service: Sense = new Sense({ progress: this.prog, config: () => SENSE, realms: REALMS,
      enabled: () => featureEnabled('spiritScan'),
      context: () => {
        const body = this.player?.body;
        return { instanceId: this.map?.id ?? '', center: { x: body?.center.x ?? Number.NaN, y: body?.center.y ?? Number.NaN },
          alive: !!this.player && !this.player.dead && this.prog.hp > 0, busy: this.senseBusy(), ready: this.sense === service && !!this.senseMap && !!body };
      },
      targets: () => [...this.senseMap.targets(), ...sceneMonsterTargets(this)],
      sources: () => [{ label: '角色加点', value: this.prog.allocatedStat('spirit') },
        { label: '已生效心法', value: this.prog.passiveBonus('spirit') }],
      text: key => { const value = t(key); return value === key ? undefined : value; },
      emit: (event, payload) => this.events.emit(event, payload) });
    this.sense = service;
  }
  private setupTalisman() {
    this.talismanSystem = new TalismanSystem(this.prog, this.quests, () => Math.random(), {
      context: () => ({ inCombat: this.inTalismanCombat(), inTrial: !!(this.trial || this.sectTrial || this.map.trial || TRIAL_BY_MAP[this.map.id]) }),
      questsForDraft: draft => new QuestSystem(draft as Progress),
    });
    this.setupTalismanUse();
  }
  private setupTalismanUse() {
    this.talismanProjectiles = [];
    this.talismanUse = new TalismanUseSystem(this.prog, {
      context: () => ({ mapId: this.map.id, alive: !this.player.dead && this.prog.hp > 0,
        available: !this.travelling && !this.dialog?.open && !this.skillWindow?.open && !this.alchemy?.isOpen()
          && !this.shop?.isOpen() && !this.attrPanel?.isOpen() && !this.scene.isActive('talisman-craft-ui')
          && this.player.state2 !== 'hurt' && this.player.state2 !== 'rope' && this.time.now >= this.player.attackLockUntil,
        inTrial: !!(this.trial || this.sectTrial || this.map.trial || TRIAL_BY_MAP[this.map.id]),
        closedBossFight: this.mobs.some(mob => { const zone = mob.arenaZone;
          return !mob.dead && !!zone?.props.bossOnly && this.player.x >= zone.x && this.player.x <= zone.x + zone.w
            && this.player.y >= zone.y && this.player.y <= zone.y + zone.h; }),
        facing: this.player.facing, visitedMaps: this.prog.visitedMaps }),
      emitProjectile: effect => this.emitTalismanFire(effect),
      prepareProjectile: effect => this.prepareTalismanFire(effect),
      returnDestination: () => this.talismanDestination(),
      validateDestination: destination => {
        if (!this.prog.visitedMaps.includes(destination.mapId)) return false;
        const reachable = this.talismanDestination([destination.mapId]);
        return !!reachable && reachable.mapId === destination.mapId && reachable.x === destination.x && reachable.y === destination.y;
      },
      teleport: destination => {
        if (!TILED_MAPS[destination.mapId] || this.travelling) return false;
        // The source data and safe landing are validated synchronously before committing the save.
        // Queue the scene transition only after the inventory transaction has had a chance to save.
        this.prog.position = { mapId: destination.mapId, x: destination.x, y: destination.y };
        const timer = this.time.delayedCall(0, () => {
          this.travelling = true; this.player.body.setVelocity(0, 0);
          this.scene.restart({ map: destination.mapId, pos: { x: destination.x, y: destination.y }, talismanReturnLand: true });
        });
        return () => timer.remove(false);
      },
    }, { now: gameNow });
  }
  private talismanDestination(visitedMaps = this.prog.visitedMaps) {
    return nearestTalismanTown(this.map.id, { level: this.prog.level, quests: this.prog.quests, visitedMaps,
      edgeOpen: edge => mapEntryOpen(edge.target, edge.source) && !(!featureEnabled('foxBoss') && edge.props.bossOnly
        && (edge.target === 'lingxi_path' || edge.props.unlockQuest === 'q_fox')) });
  }
  useTalisman(id: string, quality: 'low' | 'mid' | 'high' | 'supreme') {
    if (!featureEnabled('talismanCraft')) return { ok: false, key: 'talisman.use_unavailable' };
    if (!this.talismanUse) this.setupTalisman();
    const result = this.talismanUse.use(id, quality);
    return this.presentTalismanUse(result);
  }
  async useTalismanAsync(id: string, quality: 'low' | 'mid' | 'high' | 'supreme') {
    if (!featureEnabled('talismanCraft')) return { ok: false, key: 'talisman.use_unavailable' };
    if (!this.talismanUse) this.setupTalisman();
    const result = await this.talismanUse.useAsync(id, quality);
    return this.presentTalismanUse(result);
  }
  private presentTalismanUse(result: TalismanUseResult) {
    if (result.key) this.log(t(result.key, result.params), result.ok ? '#7fe0c0' : '#ffb0b0');
    if (result.ok && result.casting) { this.closeItemPanels(); this.gathering.cancel(); this.player.body.setVelocityX(0); }
    return result;
  }
  private interruptTalisman(reason: 'move' | 'attack' | 'damage' | 'death' | 'map') {
    if (this.talismanUse?.interrupt(reason)) {
      this.talismanReturnFx?.destroy(); this.talismanReturnFx = undefined;
      this.talismanCastText?.setVisible(false);
      this.log(t('talisman.return_interrupted'), '#ffb0b0');
    }
  }
  /** FX 只读用符状态；缺纹理或动画时保留黄块/纯逻辑，不参与结算。 */
  private createTalismanFx(atlas: string, phase: string, x: number, y: number, once = false) {
    const key = `${atlas}_${phase}`;
    if (!this.textures.exists(atlas) || !this.anims.exists(key)) return undefined;
    const animation = this.anims.get(key), texture = this.textures.get(atlas);
    if (!animation.frames.length || animation.frames.some(frame => frame.textureKey !== atlas || !texture.has(String(frame.textureFrame)))) return undefined;
    const fx = this.add.sprite(x, y, atlas, animation.frames[0].textureFrame).setDepth(12).setName(atlas)
      .setBlendMode(Phaser.BlendModes.NORMAL);
    applySpriteArt(fx);
    this.talismanFx.add(fx);
    fx.once(Phaser.GameObjects.Events.DESTROY, () => this.talismanFx.delete(fx));
    if (once) fx.once(Phaser.Animations.Events.ANIMATION_COMPLETE, () => fx.destroy());
    return fx.play(key);
  }
  private clearTalismanFx() {
    for (const fx of this.talismanFx) fx.destroy();
    this.talismanFx.clear(); this.talismanBuffFx.clear();
    for (const icon of this.talismanBuffIcons.values()) icon.destroy();
    this.talismanBuffIcons.clear(); this.talismanReturnFx = undefined;
    for (const projectile of this.talismanProjectiles) if (projectile.sprite.active) projectile.sprite.destroy();
    this.talismanProjectiles = []; this.talismanCastText?.setVisible(false);
  }
  private syncTalismanFx() {
    const now = gameNow(), state = this.prog.talismanUse;
    const buffs = state?.version === 1 && Array.isArray(state.buffs) ? state.buffs.filter(buff => buff.expireAt > now) : [];
    const layout = this.cache.json.get('talisman_ui')?.hud;
    for (const [index, id] of ['talisman_guard', 'talisman_gather'].entries()) {
      const active = buffs.some(buff => buff.itemId === id);
      let fx = this.talismanBuffFx.get(id);
      const atlas = id === 'talisman_guard' ? 'fx_talisman_guard_orbit' : 'fx_talisman_gather_buff';
      if (active) {
        if (!fx?.active) {
          fx = this.createTalismanFx(atlas, 'loop', this.player.x, this.player.y);
          if (fx) {
            this.talismanBuffFx.set(id, fx);
            if (id === 'talisman_gather') fx.setAlpha(0.65);
            const start = `${atlas}_start`, loop = `${atlas}_loop`;
            if (id === 'talisman_guard' && this.anims.exists(start)) {
              const sprite = fx;
              sprite.play(start).once(Phaser.Animations.Events.ANIMATION_COMPLETE_KEY + start, () => {
                if (sprite.active && this.talismanBuffFx.get(id) === sprite) sprite.play(loop);
              });
            }
          }
        }
        fx?.setPosition(this.player.x, this.player.y);
        const iconKey = layout?.icons?.[`buff_${id}`];
        if (!this.talismanBuffIcons.has(id) && typeof iconKey === 'string' && hasHud(this, iconKey)) {
          const size = layout.size ?? [16, 16];
          this.talismanBuffIcons.set(id, this.add.image(264 + index * 22, 34, iconKey)
            .setDisplaySize(size[0], size[1]).setScrollFactor(0).setDepth(103).setName(`buff-${id}`));
        }
      } else {
        this.talismanBuffFx.delete(id);
        if (fx?.active) {
          fx.removeAllListeners(Phaser.Animations.Events.ANIMATION_COMPLETE_KEY + `${atlas}_start`);
          const end = `${atlas}_end`;
          if (this.anims.exists(end)) fx.play(end).once(Phaser.Animations.Events.ANIMATION_COMPLETE, () => fx!.destroy());
          else fx.destroy();
        }
        this.talismanBuffIcons.get(id)?.destroy(); this.talismanBuffIcons.delete(id);
      }
    }
    if (this.talismanUse?.cast) {
      if (!this.talismanReturnFx?.active) this.talismanReturnFx = this.createTalismanFx('fx_talisman_return_cast', 'loop', this.player.x, this.player.y);
      this.talismanReturnFx?.setPosition(this.player.x, this.player.y);
    } else { this.talismanReturnFx?.destroy(); this.talismanReturnFx = undefined; }
  }
  private emitTalismanFire(effect: TalismanFireEffect) {
    const prepared = this.prepareTalismanFire(effect);
    if (prepared === false) return false;
    prepared.commit();
    return prepared.rollback;
  }
  private prepareTalismanFire(effect: TalismanFireEffect) {
    if (!this.player.active || this.player.dead) return false;
    const x = this.player.x, y = this.player.y - SPEC.bodyH / 2;
    let sprite: Phaser.GameObjects.Image | Phaser.GameObjects.Sprite | undefined = this.createTalismanFx('fx_talisman_fire_projectile', 'fly', x, y);
    if (!sprite) {
      const key = 'fx_talisman_fire_fallback';
      if (!this.textures.exists(key)) {
        const graphics = this.make.graphics({}, false);
        graphics.fillStyle(0xf2d04a).fillRect(0, 0, 18, 24).lineStyle(2, 0xe5483a).strokeRect(1, 1, 16, 22);
        graphics.generateTexture(key, 18, 24); graphics.destroy();
      }
      sprite = this.add.image(x, y, key).setDepth(12);
    }
    sprite.setFlipX(effect.facing > 0).setName('talisman-fire-projectile');
    const projectile = { sprite, effect, x, y, distance: 0, facing: effect.facing };
    sprite.setActive(false).setVisible(false);
    return {
      commit: () => { sprite.setActive(true).setVisible(true); this.talismanProjectiles.push(projectile); },
      rollback: () => { sprite.destroy(); this.talismanProjectiles = this.talismanProjectiles.filter(p => p !== projectile); },
    };
  }
  private updateTalismanUse(delta: number) {
    if (!featureEnabled('talismanCraft')) { this.clearTalismanFx(); return; }
    const cast = this.talismanUse?.cast;
    if (cast) {
      const keys = this.keys;
      if (keys.left.isDown || keys.right.isDown || keys.up.isDown || keys.down.isDown || keys.space.isDown || keys.alt.isDown || keys.c.isDown || keys.r.isDown
        || Math.abs(this.player.body.velocity.x) > 0 || Math.abs(this.player.body.velocity.y) > 0) this.interruptTalisman('move');
      if (keys.ctrl.isDown || keys.x.isDown || ['a', 's', 'd', 'f', 'g', 'h', 'q', 'w'].some(key => keys[key]?.isDown)) this.interruptTalisman('attack');
    }
    const result = this.talismanUse?.update();
    if (result?.key) this.log(t(result.key, result.params), result.ok ? '#7fe0c0' : '#ffb0b0');
    const currentCast = this.talismanUse?.cast;
    if (currentCast) {
      if (!this.talismanCastText) this.talismanCastText = this.add.text(640, 545, '', { fontFamily: HUD_FONT, fontSize: '18px', color: PAPER,
        backgroundColor: '#3b2a20dd', padding: { x: 10, y: 6 } }).setOrigin(0.5).setScrollFactor(0).setDepth(145);
      this.talismanCastText.setVisible(true).setText(t('talisman.return_cast', { town: currentCast.destination.name ?? currentCast.destination.mapId,
        seconds: (Math.max(0, currentCast.endsAt - gameNow()) / 1000).toFixed(1) }));
    } else this.talismanCastText?.setVisible(false);
    this.syncTalismanFx();
    for (const projectile of this.talismanProjectiles) {
      if (!projectile.sprite.active) continue;
      const effect = projectile.effect, distance = Math.min(effect.projectileSpeed * delta / 1000, effect.rangePx - projectile.distance);
      const fromX = projectile.sprite.x, toX = fromX + projectile.facing * distance, y = projectile.sprite.y;
      const hit = new Phaser.Geom.Rectangle(Math.min(fromX, toX) - effect.hitWidth / 2, y - effect.hitHeight / 2,
        Math.abs(toX - fromX) + effect.hitWidth, effect.hitHeight);
      const solids = this.map.solids.getChildren().filter(obj => {
        const body = obj.body as Phaser.Physics.Arcade.StaticBody;
        return Phaser.Geom.Intersects.RectangleToRectangle(hit, new Phaser.Geom.Rectangle(body.x, body.y, body.width, body.height));
      });
      const contactDistance = (body: Phaser.Physics.Arcade.Body | Phaser.Physics.Arcade.StaticBody) => Math.max(0, projectile.facing > 0
        ? body.left - effect.hitWidth / 2 - fromX : fromX - body.right - effect.hitWidth / 2);
      const firstSolid = solids.map(obj => contactDistance(obj.body as Phaser.Physics.Arcade.StaticBody)).sort((a, b) => a - b)[0];
      const monster = this.mobs.filter(mob => !mob.dead && Phaser.Geom.Intersects.RectangleToRectangle(hit,
        new Phaser.Geom.Rectangle(mob.body.x, mob.body.y, mob.body.width, mob.body.height)))
        .sort((a, b) => contactDistance(a.body) - contactDistance(b.body))[0];
      if (monster && (firstSolid === undefined || contactDistance(monster.body) < firstSolid)) {
        // Reuse the existing defense, level gap, hit, death, quest and loot pipeline with absolute configured attack.
        const dmg = this.prog.fixedDamageTo(effect.baseDamage, monster.def.level, monster.def.def);
        this.createTalismanFx('fx_talisman_fire_hit', 'hit', fromX + projectile.facing * contactDistance(monster.body), y, true);
        monster.takeHit(this.time.now, dmg, projectile.facing);
        this.damageNumber(monster.x, monster.y - monster.body.height - 10, dmg, '#ffb02e', '#6b2a00');
        projectile.sprite.destroy();
      } else if (firstSolid !== undefined) projectile.sprite.destroy();
      else { projectile.sprite.x = toX; projectile.distance += distance;
        if (projectile.distance >= effect.rangePx) projectile.sprite.destroy(); }
    }
    this.talismanProjectiles = this.talismanProjectiles.filter(projectile => projectile.sprite.active);
  }
  talismanView(recipeId?: string) {
    return featureEnabled('talismanCraft') ? this.talismanSystem?.view(recipeId) ?? null : null;
  }
  openTalisman(recipeId?: string) {
    if (!featureEnabled('talismanCraft') || this.player.dead || this.dialog.open || this.skillWindow.open || this.alchemy.isOpen()
      || this.shop.isOpen() || this.attrPanel?.isOpen() || this.trial || this.sectTrial || this.map.trial || TRIAL_BY_MAP[this.map.id]
      || this.travelling || this.inTalismanCombat()) return false;
    if (!this.talismanSystem) this.setupTalisman();
    this.gathering.cancel(); this.closeItemPanels(); this.player.body.setVelocity(0, 0);
    this.playerInput.clear(); this.playerPhysicsAccumulator = 0;
    const initialHeld = (['up', 'down', 'left', 'right'] as const).filter(direction => this.keys[direction]?.isDown);
    this.input.keyboard?.resetKeys();
    if (this.input.keyboard) this.input.keyboard.enabled = false;
    if (!this.scene.get('talisman-craft-ui')) this.scene.add('talisman-craft-ui', TalismanScene, false);
    this.physics.pause(); this.scene.launch('talisman-craft-ui', { owner: this, system: this.talismanSystem, recipeId, initialHeld }); this.scene.pause();
    return true;
  }
  private learnTalisman(npcId: string) {
    if (!featureEnabled('talismanCraft')) return;
    const npc = NPCS[npcId];
    if (this.quests.state('q_talisman_intro') === 'done') {
      this.dialog.show([{ speaker: npc.name, text: t('talisman.intro_done') }], npc.sprite); return;
    }
    if (!this.quests.isActive('q_talisman_intro') && !this.quests.available('q_talisman_intro')) {
      this.dialog.show([{ speaker: npc.name, text: t('talisman.locked') }], npc.sprite); return;
    }
    this.talkTo(npcId, 'q_talisman_intro', true);
  }

  openAlchemy(publicFurnace?: string) {
    if (this.attrPanel?.isOpen()) return false;
    if (!this.requireFeature('alchemyPhase1')) return false;
    if (this.player.dead || this.trial || this.map.trial || this.dialog.open || this.skillWindow.open || this.shop.isOpen() || this.sectTrial?.blocksInput) return false;
    const furnace = alchemyFurnace(this.prog, this.player, this.map.objects, publicFurnace);
    if (!furnace) { this.log('请到孙郎中处使用丹炉，或先获得丹炉。', '#ffb0b0'); return false; }
    this.gathering.cancel(); this.player.body.setVelocityX(0);
    this.closeItemPanels(); this.invText.setVisible(false);
    this.alchemy.open(furnace); return true;
  }

  /** UI-6：P 与测试入口共用互斥检查；加点结算由 Progress 负责。 */
  openAttrPanel(): boolean {
    if (this.player.dead || this.dialog.open || this.skillWindow.open || this.alchemy.isOpen()
      || this.shop.isOpen() || this.sectTrial?.blocksInput) return false;
    this.gathering.cancel(); this.player.body.setVelocityX(0); this.invText.setVisible(false);
    this.closeItemPanels();
