  }

  /** 测试覆盖即时撤下旧回调；存档身份、材料、贡献与待炼炉次均保留。 */
  async applyFeatureFlags() {
    this.senseMap?.syncRevealed();
    this.senseUi?.refresh(); this.attrPanel?.update();
    syncTalismanMapAvailability();
    const removedGate = (id: string | undefined) => !!id && SECT_GATE_MAPS.has(id) && !TILED_MAPS[id];
    if (removedGate(this.map.id) || removedGate(this.prog.pendingSectTrial?.returnPosition.mapId)) {
      const town = TILED_MAPS.luoxia_town;
      const spawn = town.layers.flatMap((layer: { objects?: { type: string; x: number; y: number }[] }) => layer.objects ?? [])
        .find((object: { type: string }) => object.type === 'playerStart');
      if (spawn) {
        const position = { mapId: 'luoxia_town', x: spawn.x, y: spawn.y };
        if (this.prog.pendingSectTrial && removedGate(this.prog.pendingSectTrial.returnPosition.mapId)) {
          if (featureEnabled('indexedDbSaves')) {
            await this.prog.runSaveTransactionAsync(draft => { draft.pendingSectTrial!.returnPosition = { ...position }; return true; });
          } else this.prog.runSaveTransaction(() => { this.prog.pendingSectTrial!.returnPosition = { ...position }; return true; });
        }
        if (removedGate(this.map.id) && !this.travelling) {
          this.interruptTalisman('map');
          if (this.scene.isActive('talisman-craft-ui')) this.scene.stop('talisman-craft-ui');
          this.closeItemPanels(); this.dialog?.dismiss();
          // Gate closure is a safe relocation, with no death or restoration settlement.
          const saved = featureEnabled('indexedDbSaves')
            ? await this.prog.setPosition(position.mapId, position.x, position.y, { async: true })
            : this.prog.setPosition(position.mapId, position.x, position.y);
          if (saved) {
            this.travelling = true; this.player.body.setVelocity(0, 0);
            this.scene.restart({ map: position.mapId, pos: { x: position.x, y: position.y } });
            return;
          }
        }
      }
    }
    this.dialog?.dismiss(); this.skillWindow?.close(); this.shop?.update();
    this.refreshHelpText();
    if (featureEnabled('talismanCraft') && !this.talismanSystem) { this.setupTalisman(); this.rememberMapVisited(); }
    if (!featureEnabled('talismanCraft')) { this.interruptTalisman('map'); this.clearTalismanFx(); if (this.scene.isActive('talisman-craft-ui')) this.scene.stop('talisman-craft-ui'); }
    this.inventoryPanel?.update(); this.equipPanel?.update();
    if (this.sectTrial && !this.sectTrial.ended && (!featureEnabled('fiveSectClasses') || !featureEnabled('v05Maps'))) this.sectTrial.exit();
    if (!featureEnabled('foxBoss')) {
      // 只撤下战斗，不触发死亡结算，也不改任务击杀、背包或已领取奖励。
      for (const m of this.mobs) if (m.def.id === 'demon_fox' || m.owner?.def.id === 'demon_fox') {
        // 已死首领仍有重生计时器；销毁后原回调会因 inactive 放弃重生。
        if (m.dead && !m.despawning) m.destroy();
        else m.despawn();
      }
    }
    if (!featureEnabled('alchemyPhase1')) {
      this.alchemy?.suspend(); this.gathering?.update(0, false, true);
    }
    if (featureEnabled('sectDaily')) {
      const count = this.map.objects.length;
      this.mountDailyEnvoys();
      this.map.objects.slice(count).forEach(o => this.drawObject(o));
    }
    const entranceObjects = this.map.objects.length;
    this.mountSectTrialEntrance();
    this.map.objects.slice(entranceObjects).forEach(o => this.drawObject(o));
    const exitName = '__feature_return';
    const needsExit = FIRST_CLASS_TRIAL_MAPS.has(this.map.id)
      && (!featureEnabled('v05Maps') || !featureEnabled('fiveSectClasses'))
      && !this.map.objects.some(o => o.name === '__sect_trial_gate_return'
        && SECT_GATE_MAPS.has(o.props.target) && TILED_MAPS[o.props.target]
        && mapEntryOpen(o.props.target, this.map.id));
    const exit = this.map.objects.find(o => o.name === exitName);
    if (needsExit && !exit) {
      const object: MapObj = { type: 'portal', name: exitName, x: this.map.spawn.x, y: this.map.spawn.y,
        w: 0, h: 0, props: { target: 'qingyun_village', featureExit: true } };
      this.map.objects.unshift(object); this.drawObject(object);
    } else if (!needsExit && exit) {
      this.map.objects = this.map.objects.filter(o => o !== exit);
      this.portalVisuals = this.portalVisuals.filter(visual => {
        if (visual.object !== exit) return true;
        this.tweens.killTweensOf(visual.art); visual.art.destroy(); visual.label?.destroy(); return false;
      });
    }
    for (const visual of this.portalVisuals) {
      const shut = !this.portalOpen(visual.object);
      if (visual.art instanceof Phaser.GameObjects.Sprite)
        this.playPropAnimation(visual.art, shut ? 'prop_portal_closed' : 'prop_portal_open');
      else visual.art.setFillStyle(shut ? 0x888888 : 0x8fe3ff, 0.55).setStrokeStyle(3, shut ? 0x555555 : 0x3a9fd8);
      const text = visual.object.props.featureExit ? '回青云村 ↑'
        : this.portalFeatureOpen(visual.object) ? '' : FEATURE_UNAVAILABLE;
      if (text) (visual.label ??= this.portalStatusLabel(visual.object, text)).setText(text);
      else { visual.label?.destroy(); visual.label = undefined; }
    }
    for (const label of this.seclusionLabels) label.setText(featureEnabled('seclusion') ? '闭关室 ↑' : FEATURE_UNAVAILABLE);
  }

  /** NPC 表已登记日常，地图点位尚缺；四宗山门未发布时只给本宗弟子在落霞镇补同一接引人。 */
  private mountDailyEnvoys() {
    if (!featureEnabled('sectDaily')) return;
    for (const npc of Object.values(NPCS)) {
      if (!inPhase(npc)) continue;
      const daily = (npc.quests ?? []).map(id => QUESTS_REF[id]).find(q => q?.daily && q.giver === npc.id);
      if (!daily) continue;
      const atRegisteredMap = npc.map === this.map.id;
      const atFallback = !TILED_MAPS[npc.map] && this.map.id === 'luoxia_town' && this.prog.sect === daily.sect;
      if (!(atRegisteredMap || atFallback) || this.map.objects.some(o => o.type === 'npc' && (o.props.npc ?? o.name) === npc.id)) continue;
      this.map.objects.push({ type: 'npc', name: npc.id, x: this.map.spawn.x + 96, y: this.map.spawn.y,
        w: 0, h: 0, props: { npc: npc.id } });
    }
  }

  /** 误落试炼图时优先留回山门出口；缺山门才补本宗接取、确认和交付入口。 */
  private mountSectTrialEntrance() {
    const def = Object.values(TRIALS).find(tr => tr.quest && tr.map === this.map.id);
    if (!def?.quest || this.prog.pendingSectTrial) return;
    const quest = QUESTS_REF[def.quest];
    if (!quest) return;
    const gateId = NPCS[quest.turnIn]?.map;
    const hasGate = !!TILED_MAPS[gateId];
    if (!hasGate) {
      if (!featureEnabled('fiveSectClasses') || !featureEnabled('v05Maps')) return;
      for (const [index, id] of [quest.giver, quest.turnIn].entries()) {
        if (this.map.objects.some(o => o.type === 'npc' && (o.props.npc ?? o.name) === id)) continue;
        this.map.objects.push({ type: 'npc', name: id, x: this.map.spawn.x + 48 + index * 80, y: this.map.spawn.y,
          w: 0, h: 0, props: { npc: id, sectTrialEntrance: true } });
      }
    }
    const target = hasGate ? gateId : 'luoxia_town';
    if (!this.map.objects.some(o => o.type === 'portal' && o.props.target === target)) {
      this.map.objects.push({ type: 'portal', name: '__sect_trial_gate_return', x: this.map.spawn.x - 48, y: this.map.spawn.y,
        w: 0, h: 0, props: { target } });
    }
  }

  drawObject(o: MapObj, secretTheme?: string) {
    if (this.map?.id === 'youying_tower' && o.name === 'tower_climb_entrance') {
      // 正式路径仍只画关闭入口；独立内存图可由同一对象进入塔内占位。
      this.add.rectangle(o.x, o.y - 34, 48, 68, 0x55536b).setStrokeStyle(2, 0x292638).setDepth(4)
        .setName(o.name).setInteractive({ useHandCursor: true }).on('pointerdown', () => {
          if (!this.player.dead && !this.dialog.open && !this.travelling) void this.interactTowerEntrance();
        });
      this.add.text(o.x, o.y + 6, isTowerOpenForFixture() ? '锁妖塔' : towerFeatureClosed().text,
        { fontSize: '12px', color: '#fff8d0', stroke: '#3b2a20', strokeThickness: 3 }).setOrigin(0.5, 0).setDepth(4);
      const prompt = interactionPrompt(this, o.x, o.y - 96, 'Z', isTowerOpenForFixture() ? '进入锁妖塔' : '查看说明（未开放）');
      this.interactionPrompts.push({ object: o, prompt });
    } else if (o.name === 'secret_nest_sign' || o.name === 'secret_nest_entrance') {
      const entrance = o.name === 'secret_nest_entrance';
      let visual: Phaser.GameObjects.Sprite | Phaser.GameObjects.Rectangle;
      if (entrance && this.textures.exists('prop_secret_door')) {
        const door = this.add.sprite(o.x, o.y, 'prop_secret_door').setOrigin(0.5, 1).setDepth(4);
        this.playPropAnimation(door, 'prop_secret_door_closed');
        visual = door;
      } else {
        if (!entrance) this.add.rectangle(o.x, o.y - 16, 6, 32, 0x6b4b2b).setDepth(4);
        visual = this.add.rectangle(o.x, o.y - (entrance ? 34 : 42), entrance ? 48 : 40, entrance ? 68 : 28,
          entrance ? 0x777367 : 0xc1a578).setStrokeStyle(2, 0x554a38).setDepth(4);
      }
      visual.setName(o.name).setInteractive({ useHandCursor: true }).on('pointerdown', () => {
        if (!this.player.dead && !this.dialog.open && !this.travelling && !this.secretNestRoom) this.interactSecretNest(o.name);
      });
      const enabled = isSecretNestIntroEnabled();
      this.add.text(o.x, o.y + 6, entrance ? enabled ? '万妖巢穴入口' : featureClosed().text : '巢穴路牌',
        { fontSize: '12px', color: '#fff8d0', stroke: '#3b2a20', strokeThickness: 3 }).setOrigin(0.5, 0).setDepth(4);
      const prompt = interactionPrompt(this, o.x, o.y - 96, 'Z', entrance
        ? enabled ? '进入巢穴' : '查看说明（未开放）' : enabled ? '阅读路牌' : '阅读路牌（未开放）');
      this.interactionPrompts.push({ object: o, prompt });
    } else if (o.type === 'encounter_anchor' || o.type === 'hidden' && o.props.encounter) {
      this.syncEncounterProps();
    } else if (o.type === 'npc') {
      const npc = NPCS[o.props.npc ?? o.name];
      const c = this.add.container(o.x, o.y).setDepth(5).setAlpha(o.props.phantom ? 0.55 : 1);
      let h = 70;
      if (npc && this.textures.exists(npc.sprite)) {
        const sp = this.add.sprite(0, 0, npc.sprite).setOrigin(0.5, 1).setFlipX(o.x < this.map.width / 2);
        if (this.anims.exists(`${npc.sprite}_idle`)) sp.play(`${npc.sprite}_idle`);
        applySpriteArt(sp);
        c.add(sp); h = sp.displayHeight - 10;
      } else {
        c.add(this.add.rectangle(0, -28, 30, 56, 0xf2d9a0).setStrokeStyle(2, 0x5a4020));
        c.add(this.add.circle(0, -62, 16, 0xffe0c2).setStrokeStyle(2, 0x5a4020));
      }
      c.add(this.add.text(0, 6, npc?.name ?? o.name, { fontFamily: 'sans-serif', fontSize: '12px', color: '#fff', backgroundColor: '#3a2a10cc', padding: { x: 4, y: 2 } }).setOrigin(0.5, 0));
      const mark = this.add.text(0, -h - 8, '', { fontFamily: 'Arial Black, sans-serif', fontSize: '26px', color: '#ffd23a', stroke: '#6b3a00', strokeThickness: 5 }).setOrigin(0.5, 1);
      c.add(mark);
      this.tweens.add({ targets: mark, y: mark.y - 6, yoyo: true, repeat: -1, duration: 500 });
      // 任务标记图（hud_ui.json 的 origin），三张都在才换图，否则保留文字
      let img: Phaser.GameObjects.Image | undefined;
      if (QUEST_MARK_KEYS.every(k => this.textures.exists(k))) {
        const sp = hudSpec(this, 'ui_hud_quest_available');
        img = this.add.image(0, -h - 8, 'ui_hud_quest_available').setOrigin(sp?.origin?.[0] ?? 0.5, sp?.origin?.[1] ?? 1).setVisible(false);
        c.add(img);
        this.tweens.add({ targets: img, y: img.y - 6, yoyo: true, repeat: -1, duration: 500 });
      }
      if (npc) this.npcMarks.push({ id: npc.id, text: mark, img });
      const label = npc?.id === 'doctor_sun' && featureEnabled('alchemyPhase1') ? '对话 / L 炼丹' : '对话';
      const prompt = interactionPrompt(this, o.x, o.y - h - 38, 'Z', label);
      this.interactionPrompts.push({ object: o, prompt, marker: img ?? mark });
    } else if (o.type === 'furnace' || o.type === 'alchemy') {
      const furnace = String(o.props.furnace ?? o.props.item ?? 'bronze_furnace');
      const image = `ui_alchemy_furnace_${furnace}`;
      if (this.textures.exists(image)) this.add.image(o.x, o.y, image).setOrigin(0.5, 1).setDisplaySize(64, 64).setDepth(4);
      const prompt = interactionPrompt(this, o.x, o.y - 76, 'Z', t('alchemy.title'));
      this.interactionPrompts.push({ object: o, prompt });
    } else if (o.type === 'portal') {
      const shut = !this.portalOpen(o);
      let art: Phaser.GameObjects.Ellipse | Phaser.GameObjects.Sprite;
      if (this.textures.exists('prop_portal')) {
        const sprite = this.add.sprite(o.x, o.y, 'prop_portal').setOrigin(0.5, 1).setDepth(4);
        this.playPropAnimation(sprite, shut ? 'prop_portal_closed' : 'prop_portal_open');
        art = sprite;
      } else {
        const g = this.add.ellipse(o.x, o.y - 40, 46, 80, shut ? 0x888888 : 0x8fe3ff, 0.55).setStrokeStyle(3, shut ? 0x555555 : 0x3a9fd8).setDepth(4);
        if (!shut) this.tweens.add({ targets: g, scaleX: 0.85, yoyo: true, repeat: -1, duration: 700 });
        art = g;
      }
      const text = o.props.featureExit ? '回青云村 ↑' : this.portalFeatureOpen(o) ? '' : FEATURE_UNAVAILABLE;
      const label = text ? this.portalStatusLabel(o, text) : undefined;
      art.setName('portal:' + o.name);
      this.senseMap?.bindVisual(o, art);
      this.portalVisuals.push({ object: o, art, label });
    } else if (o.type === 'chest') {
      const opened = this.prog.openedChests.includes(`${this.map.id}:${o.name}`);
      const revealed = this.map.hidden?.some(hidden => hidden.target === o) && this.senseMap?.objectVisible(o) === true;
      const prop = resolveSecretProp(o, secretTheme, { opened, revealed })!;
      if (this.textures.exists(prop.atlas)) {
        const sprite = this.add.sprite(o.x, o.y, prop.atlas).setOrigin(0.5, 1).setDepth(4).setName('chest:' + o.name);
        this.playPropAnimation(sprite, `${prop.atlas}_${prop.state}`);
        this.senseMap?.bindVisual(o, sprite);
      } else {
        const chest = this.add.rectangle(o.x, o.y - 14, 34, 28, opened ? 0x7a5a3a : 0xd9a43a).setStrokeStyle(2, 0x5a3418).setDepth(4).setName('chest:' + o.name);
        this.senseMap?.bindVisual(o, chest);
      }
    } else if (o.type === 'roomDoor' || o.type === 'restPoint' || o.type === 'event' || o.type === 'zone') {
      const prop = resolveSecretProp(o, secretTheme);
      if (!prop || !this.textures.exists(prop.atlas)) return;
      // 陷阱矩形覆盖整段站面；64×32 原图按脚底平铺，不改变 zone 碰撞或布局。
      const count = o.type === 'zone' ? Math.max(1, Math.ceil(o.w / 64)) : 1;
      for (let index = 0; index < count; index++) {
        const x = o.type !== 'zone' ? o.x : count === 1 ? o.x + o.w / 2 : o.x + 32 + index * (o.w - 64) / (count - 1);
        const y = o.type === 'zone' ? o.y + o.h : o.y;
        const sprite = this.add.sprite(x, y, prop.atlas).setOrigin(0.5, 1).setDepth(4)
          .setName(`${o.type}:${o.name}${o.type === 'zone' ? ':' + index : ''}`);
        this.playPropAnimation(sprite, `${prop.atlas}_${prop.state}`);
        this.senseMap?.bindVisual(o, sprite);
      }
    } else if (o.type === 'ferry' && this.textures.exists('prop_ferry_boat')) {
      // 落霞镇的 y 是甲板面，其他停靠点的 y 是船底；图片只做演出。
      const boat = this.add.sprite(o.x + o.w / 2, o.y + (this.map.id === 'luoxia_town' ? 96 : 0), 'prop_ferry_boat')
        .setOrigin(0.5, 1).setDepth(3).setName(`ferry:${o.name}`);
      if (this.anims.exists('prop_ferry_boat_idle')) boat.play('prop_ferry_boat_idle');
    } else if (o.type === 'seclusion') {
      let promptY = o.y - 48;
      if (this.textures.exists('prop_seclusion_door')) {
        const door = this.add.sprite(o.x, o.y, 'prop_seclusion_door').setOrigin(0.5, 1).setDepth(4);
        this.playPropAnimation(door, 'prop_seclusion_door_idle');
        promptY = o.y - door.displayHeight - 6;
      }
      this.seclusionLabels.push(this.add.text(o.x, promptY, featureEnabled('seclusion') ? '闭关室 ↑' : FEATURE_UNAVAILABLE,
        { fontSize: '13px', color: '#fff8d0', stroke: '#3b2a20', strokeThickness: 3 }).setOrigin(0.5, 1).setDepth(4));
    }
  }

  private playPropAnimation(sprite: Phaser.GameObjects.Sprite, key: string) {
    playPropAnimation(this, sprite, key);
  }

  /** 主题由秘境调用方传入；未建立主题会话时使用默认地刺皮。 */
  drawSecretTrapZones(secretTheme?: string) {
    for (const zone of this.map.zones) if (zone.props.hazard === 'trap') this.drawObject({ ...zone, type: 'zone' }, secretTheme);
  }

  /** G7/G8：等级先判；locked 永久关闭；任务须已完成；目标地图须已注册。 */
  private portalStatusLabel(o: MapObj, text: string) {
    const label = this.add.text(o.x, o.y - 92, text,
      { fontSize: '13px', color: '#fff8d0', stroke: '#3b2a20', strokeThickness: 3 }).setOrigin(0.5, 1).setDepth(4);
    this.senseMap?.bindVisual(o, label);
    return label;
  }

  private portalFeatureOpen(o: { props: any }) {
    // 普通灵溪道入口和旧档返程照常；仅标记为首领专用的妖狐入口随开关关闭。
    if (!featureEnabled('foxBoss') && o.props.bossOnly
      && (o.props.target === 'lingxi_path' || o.props.unlockQuest === 'q_fox')) return false;
    return mapEntryOpen(o.props.target, this.map.id);
  }

  portalOpen(o: { props: any }) {
    if (this.senseMap && 'type' in o && !this.senseMap.objectVisible(o as MapObj)) return false;
    if (!this.portalFeatureOpen(o)) return false;
    if (this.prog.level < Number(o.props.reqLevel ?? 0)) return false;
    if (o.props.locked) return false;
    if (o.props.unlockQuest && this.quests.state(o.props.unlockQuest) !== 'done') return false;
    const tgt = o.props.target;
    return !!tgt && (!!TILED_MAPS[tgt] || tgt === 'field_test');
  }

  tryInteract(): boolean {
    if (this.travelling) return true;
    if (this.tryInteractTowerClosed()) return true;
    if (this.tryInteractMarketConsign()) return true;
    if (this.tryInteractForgeEntrance()) return true;
    if (this.tryInteractSecretNest()) return true;
    if (this.encounterRuntime?.interact()) return true;
    const p = this.player;
    for (const o of this.map.objects) {
      if (this.senseMap?.objectVisible(o) === false) continue;
      const nearX = o.type === 'ferry' && o.w > 0 ? p.x >= o.x - 28 && p.x <= o.x + o.w + 28 : Math.abs(o.x - p.x) <= 28;
      if (!nearX || Math.abs(o.y - p.y) > 40) continue;
      if (this.trialObjects?.interact(o)) return true;
      if (o.type === 'portal') {
        if (!this.portalFeatureOpen(o)) { this.log(FEATURE_UNAVAILABLE, '#aaaaaa'); return true; }
        if (this.prog.level < Number(o.props.reqLevel ?? 0)) { this.log(t('sys.portal_level', { lv: o.props.reqLevel }), '#aaaaaa'); return true; }
        if (!this.portalOpen(o)) { this.log(t('sys.portal_locked'), '#aaaaaa'); return true; }
        this.travelToMap(o.props.target, o.props.targetPortal);
        return true;
      }
      if (o.type === 'ferry') {
        if (o.props.returnTo) this.travelToMap(o.props.returnTo, o.props.targetPortal, true);
        else if (o.props.npc) this.talkTo(o.props.npc);
        return true;
      }
      if (o.type === 'seclusion') {
        this.offerSeclusion(o);
        return true;
      }
      if (o.type === 'npc') { this.talkTo(o.props.npc ?? o.name); return true; }
    }
    return false;
  }

  /** 只拦山门中的爬塔对象；抵达渡口、宗门 NPC 和试炼仍走既有交互。 */
  private tryInteractTowerClosed(): boolean {
    if (this.map.id !== 'youying_tower') return false;
    const entrance = this.map.objects.find(o => o.name === 'tower_climb_entrance'
      && this.senseMap?.objectVisible(o) !== false
      && Math.abs(o.x - this.player.x) <= 28 && Math.abs(o.y - this.player.y) <= 40);
    if (!entrance) return false;
    if (isTowerOpenForFixture()) void this.interactTowerEntrance();
    else this.showTowerClosed();
    return true;
  }

  /** 仅接既有寄售入口的冒烟提示；未布置对象的地图保持安静。 */
  private tryInteractMarketConsign(): boolean {
    const entrance = this.map.objects.find(o => ['market_consign_entrance', 'fangshi_consign'].includes(o.name)
      && this.senseMap?.objectVisible(o) !== false
      && Math.abs(o.x - this.player.x) <= 28 && Math.abs(o.y - this.player.y) <= 40);
    if (!entrance) return false;
    if (!isMarketOpenForFixture()) this.log(marketFeatureClosed().text, '#aaaaaa');
    else {
      const result = new MarketGate(this.prog).feature();
      this.log(result.allowed ? '坊市寄售已开放。' : result.text, result.allowed ? '#fff8d0' : '#aaaaaa');
    }
    return true;
  }

  /** 仅接既有欧冶匠冒烟提示；未布置对象的地图保持安静。 */
  private tryInteractForgeEntrance(): boolean {
    const entrance = this.map.objects.find(o => (o.name === 'smith_ou' || o.props?.npc === 'smith_ou')
      && this.senseMap?.objectVisible(o) !== false
      && Math.abs(o.x - this.player.x) <= 28 && Math.abs(o.y - this.player.y) <= 40);
    if (!entrance) return false;
    if (!isForgeOpenForFixture()) this.log(forgeFeatureClosed().text, '#aaaaaa');
    else {
      const result = new ForgeGate(this.prog).entrance();
      this.log(result.allowed ? '炼器打造已开放。' : result.text, result.allowed ? '#fff8d0' : '#aaaaaa');
    }
    if (!isEnhanceOpenForFixture()) this.log(enhanceFeatureClosed().text, '#aaaaaa');
    else {
      const result = new EnhanceGate(this.prog).entrance();
      this.log(result.allowed ? '装备强化已开放。' : result.text, '#aaaaaa');
    }
    if (!isEnchantOpenForFixture()) this.log(enchantFeatureClosed().text, '#aaaaaa');
    else {
      const result = new EnchantGate(this.prog).entrance();
      this.log(result.allowed ? '装备附灵已开放。' : result.text, '#aaaaaa');
    }
    if (!isSalvageOpenForFixture()) this.log(salvageFeatureClosed().text, '#aaaaaa');
    else {
      const result = new SalvageGate(this.prog).entrance();
      this.log(result.allowed ? '装备分解已开放。' : result.text, '#aaaaaa');
    }
    return true;
  }

  /** 说明可关闭重读；没有开爬选项、传送目标或结束后写入回调。 */
  private showTowerClosed() {
    const entrance = towerEntranceClosed(), feature = towerFeatureClosed();
    this.player.body.setVelocityX(0);
    this.log(entrance.text, '#aaaaaa');
    this.dialog.show([{ speaker: null, text: entrance.text }, { speaker: null, text: feature.text }], null);
  }

  /** 只认山门既有爬塔对象；异步保存确认后才创建房内视图。 */
  private async interactTowerEntrance(): Promise<boolean> {
    if (!isTowerOpenForFixture()) { this.showTowerClosed(); return false; }
    if (this.towerBusy || this.towerGate?.session || this.secretNestRoom) return false;
    const entrance = this.map.id === 'youying_tower'
      ? this.map.objects.find(object => object.name === 'tower_climb_entrance') : undefined;
    if (!entrance) return false;
    const gate = new TowerGate(this.prog);
    this.towerGate = gate; this.towerBusy = true;
    try {
      const result = await gate.startClimb(entrance.name, { mapId: this.map.id, x: entrance.x, y: entrance.y });
      // 保存期间若场景已经销毁，不能在新场景补建旧房间。
      if (this.towerGate !== gate) return false;
      if (!result.allowed) { this.log(result.text, '#aaaaaa'); return false; }
      this.enterTowerRoom();
      return true;
    } finally { if (this.towerGate === gate) this.towerBusy = false; }
  }

  /** 占位房只持有视图与暂停所有权，进度及清层口径始终由真实门禁管理。 */
  private enterTowerRoom() {
    if (!isTowerOpenForFixture() || !this.towerGate?.session || this.towerRoomView) return;
    this.closeItemPanels(); this.gathering?.cancel();
    this.player.body.setVelocityX(0); this.playerInput?.clear(); this.playerPhysicsAccumulator = 0;
    this.towerOwnsPause = !this.physics.world.isPaused;
    if (this.towerOwnsPause) this.physics.pause();
    this.towerOwnsTimerPause = !this.time.paused;
    if (this.towerOwnsTimerPause) this.time.paused = true;
    this.renderTowerRoom();
  }

  private renderTowerRoom() {
    if (!isTowerOpenForFixture()) return;
    const room = this.towerGate?.session;
    if (!room) return;
    this.towerRoomView?.destroy();
    const width = this.scale.width, height = this.scale.height, cx = width / 2, cy = height / 2;
    const view = this.add.container(0, 0).setScrollFactor(0).setDepth(4000).setName('tower_room_stub');
    this.towerRoomView = view;
    const backdrop = this.add.rectangle(cx, cy, width, height, 0x151421).setInteractive();
    const chamber = this.add.rectangle(cx, cy, Math.min(640, width - 48), Math.min(360, height - 80), 0x363249)
      .setStrokeStyle(3, 0x9283ad);
    const title = this.add.text(cx, cy - 112, `锁妖塔·第 ${room.floor} 层`,
      { fontSize: '22px', color: '#fff1c7' }).setOrigin(0.5);
    const description = this.add.text(cx, cy - 48, room.completed ? '三十层妖物已清，通塔完成。'
      : room.cleared ? '本层已清，可前往下一层。' : `本层尚余妖物 ${room.mobs.filter(mob => mob.alive).length} 只。`,
      { fontSize: '16px', color: '#ddd4ed' }).setOrigin(0.5);
    const next = this.add.text(cx, cy + 16, room.completed ? '已通塔' : '前往下一层',
      { fontSize: '18px', color: '#fff1c7', backgroundColor: '#514667', padding: { x: 16, y: 10 } })
      .setOrigin(0.5).setName('tower_stub_next').setInteractive({ useHandCursor: true })
      .on('pointerdown', () => { void this.advanceTowerRoom(); });
    const exit = this.add.text(cx, cy + 104, '返回山门  [Z / ↑ / Esc]',
      { fontSize: '18px', color: '#fff1c7', backgroundColor: '#514667', padding: { x: 16, y: 10 } })
      .setOrigin(0.5).setName('tower_stub_exit').setInteractive({ useHandCursor: true })
      .on('pointerdown', () => { void this.exitTowerRoom(); });
    view.add([backdrop, chamber, title, description, next, exit]);
  }

  private async advanceTowerRoom(): Promise<boolean> {
    if (!isTowerOpenForFixture() || this.towerBusy || !this.towerGate?.session) return false;
    const gate = this.towerGate; this.towerBusy = true;
    try {
      const result = await gate.advanceFloor();
      if (this.towerGate !== gate) return false;
      if (!result.allowed) this.log(result.text, '#aaaaaa');
      this.renderTowerRoom();
      return result.allowed;
    } finally { if (this.towerGate === gate) this.towerBusy = false; }
  }

  private async exitTowerRoom(): Promise<boolean> {
    if (!isTowerOpenForFixture() || this.towerBusy || !this.towerGate?.session) return false;
    const gate = this.towerGate; this.towerBusy = true;
    try {
      const result = await gate.exitClimb();
      if (this.towerGate !== gate) return false;
      if (!result.allowed) { this.log(result.text, '#aaaaaa'); return false; }
      if (!result.returnPosition) return false;
      this.towerRoomView?.destroy(); this.towerRoomView = undefined;
      this.towerGate = undefined;
      this.player.body.reset(result.returnPosition.x, result.returnPosition.y);
      this.player.body.setVelocityX(0); this.playerInput?.clear(); this.playerPhysicsAccumulator = 0;
      // 等待保存时可能又按了退出键；消费残留，避免回山门后同一按键再次开爬。
      for (const key of [this.keys.z, this.keys.up, this.keys.esc]) Phaser.Input.Keyboard.JustDown(key);
      if (this.towerOwnsPause) this.physics.resume();
      if (this.towerOwnsTimerPause) this.time.paused = false;
      this.towerOwnsPause = false; this.towerOwnsTimerPause = false;
      this.log('已退出锁妖塔，返回幽影楼山门。', '#ffe680');
      return true;
    } finally { if (this.towerGate === gate || !this.towerGate) this.towerBusy = false; }
  }

  /** 门禁先于通用传送/试炼路径；return 只在占位房内执行，不抢营地 NPC。 */
  private tryInteractSecretNest(): boolean {
    for (const o of this.map.objects) {
      if (!['secret_nest_sign', 'secret_nest_entrance'].includes(o.name)
        || this.senseMap?.objectVisible(o) === false || Math.abs(o.x - this.player.x) > 28 || Math.abs(o.y - this.player.y) > 40) continue;
      this.interactSecretNest(o.name);
      return true;
    }
    return false;
  }

  private interactSecretNest(name: string) {
    if (!isSecretNestIntroEnabled()) { this.showSecretNestClosed(name); return; }
    if (this.secretNestRoom) return;
    if (name === 'secret_nest_sign') {
      const sign = readSecretNestSign();
      if (!sign.allowed) { this.showSecretNestClosed(name); return; }
      this.player.body.setVelocityX(0);
      this.log(sign.lines.join('\n'), '#ffe680');
      this.dialog.show(sign.lines.map(text => ({ speaker: null, text })), null);
      if (this.quests.isActive(SECRET_NEST_INTRO_ID)) this.quests.onReach('secret_nest_sign');
      return;
    }
    if (name !== 'secret_nest_entrance') return;
    const camp = this.map.objects.find(object => object.name === 'secret_nest_return') ?? this.map.spawn;
    const result = enterSecretNest(this.prog, { mapId: this.map.id, x: camp.x, y: camp.y });
    if (!result.allowed) {
      this.player.body.setVelocityX(0);
      this.log(result.text, '#aaaaaa');
      this.dialog.show([{ speaker: null, text: result.text }], null);
      return;
    }
    this.enterSecretNestRoom(result.room);
  }

  /** 可进入和退出的独立单房占位，仅存在于当前场景内存。 */
  private enterSecretNestRoom(room: SecretNestRoom) {
    if (this.secretNestRoom) return;
    const checked = enterSecretNest(this.prog, room.returnPosition);
    if (!checked.allowed) { this.log(checked.text, '#aaaaaa'); return; }
    this.closeItemPanels(); this.gathering?.cancel();
    this.player.body.setVelocityX(0); this.playerInput?.clear();
    this.playerPhysicsAccumulator = 0;
    this.secretNestOwnsPause = !this.physics.world.isPaused;
    if (this.secretNestOwnsPause) this.physics.pause();
    this.secretNestOwnsTimerPause = !this.time.paused;
    if (this.secretNestOwnsTimerPause) this.time.paused = true;
    this.secretNestRoom = checked.room;
    const width = this.scale.width, height = this.scale.height;
    const cx = width / 2, cy = height / 2;
    const view = this.add.container(0, 0).setScrollFactor(0).setDepth(4000).setName(checked.room.id);
    this.secretNestRoomView = view;
    const backdrop = this.add.rectangle(cx, cy, width, height, 0x121717)
      .setInteractive();
    const chamber = this.add.rectangle(cx, cy, Math.min(640, width - 48), Math.min(360, height - 80), 0x333a35)
      .setStrokeStyle(3, 0x8d9472);
    const title = this.add.text(cx, cy - 112, '万妖巢穴·入口石室',
      { fontSize: '22px', color: '#fff1c7' }).setOrigin(0.5);
    const description = this.add.text(cx, cy - 56, '前方通道暂未开放，本次进出不发放收益。',
      { fontSize: '16px', color: '#d0d4c1' }).setOrigin(0.5);
    const visitor = this.add.text(cx, cy + 4, '◆\n你在石室中',
      { fontSize: '18px', color: '#efe6c6', align: 'center' }).setOrigin(0.5);
    const exit = this.add.text(cx, cy + 104, '返回营地  [Z / ↑ / Esc]',
      { fontSize: '18px', color: '#fff1c7', backgroundColor: '#535d48', padding: { x: 16, y: 10 } })
      .setOrigin(0.5).setName('secret_nest_stub_exit').setInteractive({ useHandCursor: true })
      .on('pointerdown', () => this.exitSecretNestRoom());
    view.add([backdrop, chamber, title, description, visitor, exit]);
  }

  private exitSecretNestRoom(): boolean {
    if (!this.secretNestRoom) return false;
    const result = exitSecretNest(this.secretNestRoom);
    if (!result.allowed) { this.log(result.text, '#aaaaaa'); return false; }
    this.secretNestRoomView?.destroy(); this.secretNestRoomView = undefined;
    this.secretNestRoom = undefined;
    this.player.body.reset(result.returnPosition.x, result.returnPosition.y);
    this.player.body.setVelocityX(0); this.playerInput?.clear(); this.playerPhysicsAccumulator = 0;
    if (this.secretNestOwnsPause) this.physics.resume();
    this.secretNestOwnsPause = false;
    if (this.secretNestOwnsTimerPause) this.time.paused = false;
    this.secretNestOwnsTimerPause = false;
    this.log('已退出万妖巢穴，返回营地。', '#ffe680');
    return true;
  }

  private showSecretNestClosed(name: string) {
    const tip = name === 'secret_nest_sign' ? readSignClosed()
      : name === 'secret_nest_entrance' ? interactEntranceClosed() : featureClosed();
    this.player.body.setVelocityX(0);
    this.log(tip.text, '#aaaaaa');
    this.dialog.show([{ speaker: null, text: tip.text }], null);
  }

  private interactTrialObject() {
    for (const o of this.map.objects) {
      if (Math.abs(o.x - this.player.x) <= 40 && Math.abs(o.y - this.player.feet) <= 48
        && this.trialObjects?.interact(o)) return true;
    }
    return false;
  }

  private async travelToMap(map: string, portal?: string, returning = false, onCancelled?: () => void) {
    syncTalismanMapAvailability();
    this.interruptTalisman('map');
    if (this.sectTrial && !this.sectTrial.ended) { this.sectTrial.exit(); return; }
    map = sectEntryMap(map);
    if (!mapEntryOpen(map, this.map.id, returning)) { onCancelled?.(); this.log(FEATURE_UNAVAILABLE, '#aaaaaa'); return; }
    if (!TILED_MAPS[map] && map !== 'field_test') { onCancelled?.(); this.log(t('sys.portal_locked'), '#aaaaaa'); return; }
    if (this.travelling) { onCancelled?.(); return; }
    this.travelling = true;
    this.player.body.setVelocityX(0);
    const terminated = featureEnabled('indexedDbSaves')
      ? await this.encounterRuntime?.terminateAsync('missed') : this.encounterRuntime?.terminate('missed');
    if (terminated === false) {
      this.travelling = false;
      onCancelled?.(); this.log(t('sect.ui.save_failed'), '#ffb0b0'); return;
    }
    this.prog.persistSoon();
    this.cameras.main.fadeOut(200);
    this.time.delayedCall(220, () => {
      if (!mapEntryOpen(map, this.map.id, returning)) {
        onCancelled?.();
        this.travelling = false; this.cameras.main.fadeIn(100); this.log(FEATURE_UNAVAILABLE, '#aaaaaa'); return;
      }
      this.scene.restart({ map, portal });
    });
  }

  /** 配表选项确认后逐年结算；退出对白不消耗资源。 */
  private offerSeclusion(o: MapObj) {
    if (!this.requireFeature('seclusion')) return;
    this.player.body.setVelocityX(0);
    const seclusion = new Seclusion(this.prog);
    if (seclusion.locked(o.props)) {
      const text = t('sys.seclusion_locked'); this.log(text, '#ffe680');
      this.dialog.show([{ speaker: null, text }], null); return;
    }
    const costs = SECT_SECLUSION.options.map(years => t('sys.seclusion_cost', {
      years, cost: SECT_SECLUSION.contributionCost[String(years)], have: this.prog.sectContribution,
    }));
    this.dialog.choose({ speaker: null, text: costs.join('\n') }, null, [
      ...SECT_SECLUSION.options.map(years => ({ label: `闭关 ${years} 年`, onSelect: () => this.completeSeclusion(o, years) })),
      { label: t('ui.dialog.close'), onSelect: () => {} },
    ]);
  }

  private completeSeclusion(o: MapObj, years: number) {
    if (!this.requireFeature('seclusion')) return;
    const result = new Seclusion(this.prog).settle(o.props, years);
    if (!result.ok) {
      const vars = { years, cost: SECT_SECLUSION.contributionCost[String(years)], have: this.prog.sectContribution,
        used: this.prog.seclusionDay === realDay() ? this.prog.seclusionYearsToday : 0, max: SECT_SECLUSION.maxYearsPerRealDay };
      const text = result.reason === 'closed' ? FEATURE_UNAVAILABLE : t(result.reason === 'locked' ? 'sys.seclusion_locked' : result.reason === 'daily'
        ? 'sys.seclusion_daily' : result.reason === 'life' ? 'sys.seclusion_life' : 'sys.seclusion_cost', vars);
      this.log(text, '#ffe680'); this.dialog.show([{ speaker: null, text }], null); return;
    }
    this.applyExp(result);
    this.log(t('sys.seclusion_done', { years: result.years, cost: result.cost, exp: result.gained,
      overflow: result.overflowed, age: Math.floor(this.prog.age) }), '#ffe680');
    if (this.prog.remainingLife <= LIFESPAN.warnAtRemaining) this.log(t('sys.lifespan_warn', { years: Math.floor(this.prog.remainingLife) }), '#ffb0b0');
  }

  // ---------------- NPC 对话与任务 ----------------
  nearNpc(): string | null {
    const p = this.player;
    for (const o of this.map.objects) if (o.type === 'npc' && Math.abs(o.x - p.x) < 40 && Math.abs(o.y - p.y) < 48) return o.props.npc ?? o.name;
    return null;
  }

  talkNearby() {
    const hasDrop = this.hasNearbyDrop();
    const id = hasDrop ? null : this.nearNpc();
    if (!id) return false;
    this.talkTo(id); return true;
  }

  /** 背包中的拜帖提供明确选择；定下去向并不提前拜入。 */
  openSectToken(): boolean {
    if (this.prog.count('five_sect_token') <= 0 || this.prog.job || this.prog.pendingSectTrial || this.player.dead
      || this.dialog.open || this.skillWindow.open || this.alchemy.isOpen() || this.shop.isOpen() || this.attrPanel?.isOpen() || this.sectTrial?.blocksInput) return false;
    this.player.body.setVelocityX(0); this.invText.setVisible(false);
    this.gathering.cancel(); this.closeItemPanels();
    this.dialog.choose({ speaker: null, text: `${t('sect.entry.select_title')}\n${t('sect.entry.select_tip')}` }, null,
      CLASS_LIST.map(cls => {
        const name = SECT_RANKS.sects.find(sect => sect.id === cls.sect)?.name ?? cls.name;
        const locked = cls.sect !== this.prog.selectedSect && Object.values(TRIALS)
          .some(tr => tr.quest && classForQuest(tr.quest) && this.prog.completedTrials.includes(tr.id));
        return { label: name, disabled: !classEntryEnabled(cls) || locked,
          reason: !classEntryEnabled(cls) ? FEATURE_UNAVAILABLE : locked ? t('sect.entry.trial_complete') : undefined,
          onSelect: async () => {
            const saved = featureEnabled('indexedDbSaves')
              ? await this.prog.runSaveTransactionAsync(draft => draft.selectSect(cls.sect) || undefined)
              : this.prog.selectSect(cls.sect);
            if (saved) this.log(t('sect.entry.selected', { sect: name }), '#ffe680');
            else this.log(t('sect.ui.save_failed'), '#ffb0b0');
          } };
      }));
    return true;
  }

  talkTo(npcId: string, questId?: string, skipMenu = false) {
    if (this.attrPanel?.isOpen()) return;
    const npc = NPCS[npcId]; if (!npc) return;
    if (this.trial || this.sectTrial || TRIAL_BY_MAP[this.map.id]) return;
    this.closeItemPanels();
    if (questId === SECRET_NEST_INTRO_ID && !isSecretNestIntroEnabled()) {
      const tip = this.prog.quests[questId] ? refuseQuestProgress() : refuseQuestOffer();
      this.player.body.setVelocityX(0);
      this.log(tip.text, '#aaaaaa');
      this.dialog.show([{ speaker: npc.name, text: tip.text }], npc.sprite);
      return;
    }
    if (npcId === 'ferry_master') {
      // 航线菜单也算与船老大交谈，供幽影宗问讯日常记录目标。
      this.quests.onTalk(npcId);
      this.player.body.setVelocityX(0);
      this.dialog.choose({ speaker: npc.name, text: npc.dialog[0] ?? '' }, npc.sprite, [
        ...(npc.ferryRoutes ?? []).map(route => {
          const reason = ferryLockedReason(route, this.prog);
          const label = `${t(route.label)}${route.cost > 0 ? `（${route.cost} ${t('ui.stone')}）` : ''}`;
          return { label, disabled: !!reason, reason, onSelect: async () => {
            const locked = ferryLockedReason(route, this.prog);
            if (locked) { this.log(locked, '#aaaaaa'); return; }
            if (this.travelling) return;
            this.prog.stones -= route.cost;
            await this.travelToMap(route.targetMap, route.targetPortal ?? undefined, false, () => {
              this.prog.stones += route.cost; this.prog.persistSoon();
            });
          } };
        }),
        { label: t('ui.dialog.close'), onSelect: () => {} },
      ]);
      return;
    }
    const hasTalismanService = featureEnabled('talismanCraft')
      && !!npc.services?.some(service => service.type === 'talisman_craft');
    // 独立制符菜单不受拜帖门槛影响；显式拜师或继续普通对话仍检查原门槛。
    const talismanMenu = hasTalismanService && !questId && !skipMenu;
    const blockedQuest = !talismanMenu && (questId || !this.prog.job) && this.quests.npcQuestIds(npcId).find(id => (!questId || id === questId)
      && this.quests.state(id) !== 'done' && this.quests.sectEntryBlock(id));
    if (blockedQuest) {
      this.player.body.setVelocityX(0);
      this.dialog.choose({ speaker: npc.name, text: this.quests.sectEntryBlock(blockedQuest)! }, npc.sprite, [
        ...(this.quests.isActive(blockedQuest) ? [{ label: t('sect.entry.abandon'), onSelect: async () => {
          const abandoned = featureEnabled('indexedDbSaves')
            ? await this.quests.abandon(blockedQuest, { async: true }) : this.quests.abandon(blockedQuest);
          if (abandoned) this.log(t('sect.entry.abandoned'), '#ffe680');
        } }] : []),
        { label: t('ui.dialog.close'), onSelect: () => {} },
      ]);
      return;
    }
    const sectOffer = this.sectTrialOfferFor(npcId, questId);
    if (sectOffer) { this.offerSectTrial(npcId, sectOffer); return; }
    const dailyIds = this.quests.npcDailyQuestIds(npcId);
    const services = this.sectGrowth.services(npcId).filter(service => (service.type !== 'sect_shop' || featureEnabled('shops'))
      && featureEnabled(service.type === 'sect_promotion'
        ? 'sectRanks' : service.type === 'sect_donation' ? 'sectDonations' : 'sectShopLibrary'));
    const ordinaryShop = this.sectGrowth.ordinaryCatalog(npcId);
    const hasOrdinaryShop = featureEnabled('shops') && (ordinaryShop.ok || this.sectGrowth.ordinarySellCatalog(npcId).ok);
    const hasRecipeShop = this.sectGrowth.recipeCatalog(npcId).ok;
    const hasSecretIntro = npcId === 'hunter_lei' && isSecretNestIntroEnabled()
      && (this.quests.available(SECRET_NEST_INTRO_ID) || this.quests.isActive(SECRET_NEST_INTRO_ID));
    if (!questId && !skipMenu && (dailyIds.length || services.length || hasOrdinaryShop || hasRecipeShop || hasTalismanService || hasSecretIntro)) {
      this.player.body.setVelocityX(0);
      const ordinaryIds = this.quests.npcQuestIds(npcId).filter(id => QUESTS_REF[id] && !QUESTS_REF[id].daily
        && (this.quests.available(id) || this.quests.isActive(id)));
      const menuTitle = t(dailyIds.length || hasSecretIntro ? 'ui.quests' : services.length ? 'sect.ui.title' : 'ui.shop.menu');
      this.dialog.choose({ speaker: npc.name, text: services.length ? `${this.sectOverview()}\n${menuTitle}` : menuTitle }, npc.sprite, [
        ...dailyIds.map(id => {
          const q = QUESTS_REF[id], state = this.quests.state(id);
          const disabled = !this.quests.isActive(id) && !this.quests.available(id);
          return { label: questName(q), disabled,
            reason: disabled ? state === 'done' ? t('quest.complete', { name: questName(q) }) : t('sect.ui.config_pending') : questDescription(q),
            onSelect: () => this.talkTo(npcId, id) };
        }),
        ...ordinaryIds.filter(id => !hasTalismanService || id !== 'q_talisman_intro').map(id => ({
          label: questName(QUESTS_REF[id]), reason: questDescription(QUESTS_REF[id]), onSelect: () => this.talkTo(npcId, id),
        })),
        ...(hasTalismanService ? [
          { label: t('talisman.entry_learn'), onSelect: () => this.learnTalisman(npcId) },
          { label: t('talisman.entry_craft'), onSelect: () => this.openTalisman() },
        ] : []),
        ...services.map(service => ({ label: t(service.type === 'sect_promotion' ? 'sect.promotion.menu'
          : service.type === 'sect_library' ? 'sect.library.menu' : service.type === 'sect_donation' ? 'sect.donation.menu' : 'sect.shop.menu'),
          reason: service.allowed ? undefined : t(service.key),
          onSelect: () => service.type === 'sect_promotion' ? this.openSectPromotion(npcId)
            : service.type === 'sect_donation' ? this.openSectDonations(npcId) : this.openSectCatalog(npcId, service.type) })),
        ...(hasOrdinaryShop ? [{ label: t('ui.shop.menu'), onSelect: () => this.openOrdinaryShop(npcId) }] : []),
        ...(hasRecipeShop ? [{ label: '学习丹方', onSelect: () => this.openRecipeShop(npcId) }] : []),
        ...(!dailyIds.length ? [{ label: t('ui.dialog.next'), onSelect: () => this.talkTo(npcId, undefined, true) }] : []),
        { label: t('ui.dialog.close'), onSelect: () => {} },
      ], services.length ? this.sectRankBadgeKey() : undefined);
      return;
    }
    const offer = !questId ? this.trialOfferFor(npcId) : null;
    if (offer) { this.offerTrial(npcId, offer); return; }
    const talked = featureEnabled('indexedDbSaves')
      ? this.quests.talk(npcId, questId, { async: true }) : this.quests.talk(npcId, questId);
    if (talked.blockedTip && !talked.after && talked.lines.every(line => line.text === talked.blockedTip!.text)) {
      this.player.body.setVelocityX(0);
      this.log(talked.blockedTip.text, '#aaaaaa');
      this.dialog.show(talked.lines, npc.sprite);
      return;
    }
    const after = talked.after;
    // 任务没有对白脚本时，用 NPC 的通用台词兜底
    const intro = featureEnabled('alchemyPhase1')
      && (this.quests.isActive('q_alchemy_intro') || this.quests.available('q_alchemy_intro'));
    const lines = talked.lines.length ? talked.lines : npcId === 'doctor_sun' && intro ? [
      { speaker: npc.name, text: '你如今入了炼气，该学学炼丹了。修仙路上，丹药就是半条命。' },
      { speaker: npc.name, text: '可先试炼回春丹：每炉用灵草二株、灵兔绒一份、灵石十枚。交付入门任务时，还须留足三株灵草。丹炉可在我这里用，学成后再送你。' },
    ] : npc.dialog.map(tx => ({ speaker: npc.name, text: tx }));
    this.player.body.setVelocityX(0);
    this.dialog.show(lines, npc.sprite, async () => {
      const activeBefore = this.quests.activeIds;
      const pending = after?.();
      const r = pending instanceof Promise ? await pending : pending;
      if (r) {
        this.giveRewards(r.quest, r.broke, r.daily, r.settled);
        const ut = (r.quest.rewards as { unlockTrial?: string }).unlockTrial;
        if (ut && TRIALS[ut]) this.time.delayedCall(150, () => { const o = this.trialOfferFor(npcId); if (o) this.offerTrial(npcId, o); });
      }
      else if (after && this.quests.activeIds.some(id => !activeBefore.includes(id))) this.log(t('quest.accept', {
        name: questId ? questName(QUESTS_REF[questId]) : this.quests.activeIds.map(i => questName(QUESTS_REF[i])).slice(-1)[0] ?? '',
      }), '#ffe680');
      this.prog.persistSoon();
      if (npcId === 'doctor_sun' && featureEnabled('alchemyPhase1') && this.quests.state('q_alchemy_intro')) this.openAlchemy('bronze_furnace');
    }, (cue, next) => this.playCue(cue, next));
  }

  private sectOverview() {
    const identity = this.sectGrowth.identity();
    return [featureEnabled('sectRanks') && identity?.title ? t('sect.ui.rank', { title: identity.title }) : '',
      t('sect.ui.contribution', { contribution: this.prog.sectContribution })].filter(Boolean).join('\n');
  }

  /** 只读取现有身份与职位表；无效身份不展示当前或目标职位徽记。 */
  private sectRankBadgeKey(rankId?: string) {
    if (!featureEnabled('sectRanks')) return undefined;
    const identity = this.sectGrowth.identity();
    if (!identity?.valid) return undefined;
    return rankId ? this.sectGrowth.config.ranks.ranks.find(rank => rank.id === rankId)?.icon : identity.icon;
  }

  openSectPromotion(npcId: string) {
    if (!this.requireFeature('sectRanks', npcId)) return;
    const npc = NPCS[npcId]; if (!npc) return;
    const offer = this.sectGrowth.promotion(npcId);
    const conditions = typeof offer.requiredContribution === 'number' && Number.isInteger(offer.requiredContribution) && offer.requiredRealmName
      ? t('sect.ui.requirements', { contribution: offer.requiredContribution, realm: offer.requiredRealmName }) : '';
    const reason = [conditions, conditions ? t('sect.ui.promotion_free') : '',
      offer.ok && offer.dialogueKeys?.offer ? t(offer.dialogueKeys.offer) : t(offer.key)].filter(Boolean).join('\n');
    this.dialog.choose({ speaker: npc.name, text: this.sectOverview() || t('sect.ui.title') }, npc.sprite, [
      { label: offer.targetRankName ? `${t('sect.ui.confirm')}（${offer.targetRankName}）` : t('sect.ui.confirm'), rankIcon: offer.target ? this.sectRankBadgeKey(offer.target) : undefined,
        disabled: !offer.ok, reason, onSelect: () => {
          if (!this.requireFeature('sectRanks', npcId)) return;
          const target = offer.target; if (!target) return;
          const transactionId = newSectTransactionId();
          const promote = async (acceptOath = false) => {
            if (!this.requireFeature('sectRanks', npcId)) return;
            const result = featureEnabled('indexedDbSaves')
              ? await this.sectGrowth.promoteAsync(npcId, target, transactionId, acceptOath)
              : this.sectGrowth.promote(npcId, target, transactionId, acceptOath);
            this.sectResult(npcId, result, {});
          };
          if (offer.mode === 'oath') {
            const keys = offer.dialogueKeys;
            this.dialog.choose({ speaker: npc.name, text: keys?.question ? t(keys.question) : t('sect.ui.config_pending') }, npc.sprite, [
              { label: keys?.accept ? t(keys.accept) : t('sect.ui.confirm'), rankIcon: this.sectRankBadgeKey(target), onSelect: () => promote(true) },
              { label: keys?.defer ? t(keys.defer) : t('sect.ui.cancel'), onSelect: () => {} },
            ], this.sectRankBadgeKey(target));
          } else promote();
        } },
      { label: t('sect.ui.cancel'), onSelect: () => {} },
    ], this.sectRankBadgeKey());
  }

  /** UI-5：宗门商店/藏经阁走商店窗；目录、职位与贡献结算仍由 SectGrowth.catalog/exchange 负责。 */
  openSectCatalog(npcId: string, service: 'sect_shop' | 'sect_library') {
    if (this.attrPanel?.isOpen()) return;
    if (!this.requireFeature('sectShopLibrary', npcId) || (service === 'sect_shop' && !this.requireFeature('shops', npcId))) return;
    if (!NPCS[npcId]) return;
    this.closeItemPanels();
    this.player.body.setVelocityX(0);
    this.shop.open({ kind: 'sect', npcId, service });
  }

  /** UI-5：普通买卖窗（列表、价格、数量、确认）；结算只调 buyOrdinary/sellOrdinary。 */
  openOrdinaryShop(npcId: string, mode: 'buy' | 'sell' = 'buy') {
    if (this.attrPanel?.isOpen()) return;
    if (!this.requireFeature('shops', npcId)) return;
    if (!NPCS[npcId]) return;
    this.closeItemPanels();
    this.player.body.setVelocityX(0);
    this.shop.open({ kind: 'ordinary', npcId, mode });
  }

  /** 丹方不是背包商品；读丹方的售价/等级，购买成功直接授方。 */
  openRecipeShop(npcId: string) {
    if (!this.requireFeature('alchemyPhase1', npcId) || !this.requireFeature('shops', npcId)) return;
    const npc = NPCS[npcId]; if (!npc) return;
    const catalog = this.sectGrowth.recipeCatalog(npcId);
    const choices: DialogChoice[] = catalog.entries.map(entry => {
      const preview = t('ui.shop.confirm', { item: `${entry.name}丹方`, price: entry.price });
      return { label: `${entry.name}丹方`, disabled: !entry.ok,
        reason: entry.ok ? preview : entry.learned ? '已学会这张丹方' : this.prog.level < entry.reqLevel
          ? `需达到 ${entry.reqLevel} 级` : t(entry.key), onSelect: () => {
          if (!this.requireFeature('alchemyPhase1', npcId) || !this.requireFeature('shops', npcId)) return;
          const transactionId = newSectTransactionId();
          this.dialog.choose({ speaker: npc.name, text: preview }, npc.sprite, [
            { label: t('sect.ui.confirm'), reason: preview, onSelect: async () => {
              if (!this.requireFeature('alchemyPhase1', npcId) || !this.requireFeature('shops', npcId)) return;
              const current = this.sectGrowth.recipeCatalog(npcId).entries.find(row => row.recipeId === entry.recipeId);
              if (!current || current.price !== entry.price || current.reqLevel !== entry.reqLevel) {
                this.openRecipeShop(npcId); return;
              }
              const result = featureEnabled('indexedDbSaves')
                ? await this.sectGrowth.buyRecipeAsync(npcId, entry.recipeId, transactionId)
                : this.sectGrowth.buyRecipe(npcId, entry.recipeId, transactionId);
              const fallback: Record<string, string> = { 'alchemy.recipe.complete': `已学会${entry.name}丹方`,
                'alchemy.recipe.learned': '已学会这张丹方', 'alchemy.recipe.level': `需达到 ${entry.reqLevel} 级` };
              this.sectResult(npcId, { ...result, key: t(result.key) === result.key ? fallback[result.key] ?? result.key : result.key },
                { item: `${entry.name}丹方`, price: entry.price });
            } },
            { label: t('sect.ui.cancel'), onSelect: () => this.openRecipeShop(npcId) },
          ]);
        } };
    });
    if (!choices.length) choices.push({ label: t(catalog.key || 'ui.shop.empty'), disabled: true, onSelect: () => {} });
    choices.push({ label: t('ui.dialog.close'), onSelect: () => {} });
    this.dialog.choose({ speaker: npc.name, text: '学习丹方' }, npc.sprite, choices);
  }

  openSectDonations(npcId: string) {
    if (!this.requireFeature('sectDonations', npcId)) return;
    const npc = NPCS[npcId]; if (!npc) return;
    const catalog = this.sectGrowth.donations(npcId);
    const warning = t('sect.donation.quest_warning');
    const choices: DialogChoice[] = catalog.entries.map(entry => {
      const values = { item: entry.name, count: entry.count, contribution: entry.contribution };
      const preview = t('sect.donation.confirm', values);
      const remaining = t('sect.donation.remaining', { remaining: entry.remaining });
      const reason = [preview, remaining, warning, entry.ok ? '' : t(entry.key, { rank: entry.rankName })].filter(Boolean).join('\n');
      return { label: `${entry.name}（${entry.rankName}）`, rankIcon: this.sectRankBadgeKey(entry.reqRank), disabled: !entry.ok, reason,
        onSelect: () => {
          if (!this.requireFeature('sectDonations', npcId)) return;
          // 一次预览绑定一次确认；缓存回调重试继续使用同一事务和日界。
          const transactionId = newSectTransactionId(), previewDay = entry.day;
          this.dialog.choose({ speaker: npc.name, text: `${this.sectOverview()}\n${reason}` }, npc.sprite, [
            { label: t('sect.ui.confirm'), rankIcon: this.sectRankBadgeKey(entry.reqRank), reason, onSelect: async () => {
              if (!this.requireFeature('sectDonations', npcId)) return;
              const current = this.sectGrowth.donations(npcId).entries.find(row => row.offerId === entry.offerId);
              if (current && (current.itemId !== entry.itemId || current.count !== entry.count
                || current.contribution !== entry.contribution || current.reqRank !== entry.reqRank)) {
                this.openSectDonations(npcId); return;
              }
              const result = featureEnabled('indexedDbSaves')
                ? await this.sectGrowth.donateAsync(npcId, entry.offerId, transactionId, previewDay)
                : this.sectGrowth.donate(npcId, entry.offerId, transactionId, previewDay);
              if (result.key === 'sect.donation.day_changed') {
                this.dialog.show([{ speaker: npc.name, text: t(result.key) }], npc.sprite, () => this.openSectDonations(npcId));
                return;
              }
              this.sectResult(npcId, result, values);
            } },
            { label: t('sect.ui.cancel'), onSelect: () => this.openSectDonations(npcId) },
          ], this.sectRankBadgeKey());
        } };
    });
    if (!choices.length) choices.push({ label: t(catalog.key || 'sect.ui.config_pending'), disabled: true, onSelect: () => {} });
    choices.push({ label: t('ui.dialog.close'), onSelect: () => {} });
    this.dialog.choose({ speaker: npc.name, text: `${this.sectOverview()}\n${t('sect.donation.menu')}\n${warning}` }, npc.sprite, choices, this.sectRankBadgeKey());
  }

  private sectResult(npcId: string, result: { ok: boolean; key: string; repeated?: boolean }, vars: Record<string, string | number>) {
    const text = t(result.key, { ...vars, title: this.sectGrowth.identity()?.title ?? '' });
    const rankIcon = result.key.startsWith('sect.promotion.') ? this.sectRankBadgeKey() : undefined;
    if (result.ok && !result.repeated) this.log(text, '#ffd23a', rankIcon);
    const npc = NPCS[npcId];
    this.dialog.show([{ speaker: npc?.name ?? null, text }], npc?.sprite ?? null, undefined, undefined, rankIcon);
  }

  applyExp(r: { gained: number; levels: number; blocked: boolean; overflowed?: number; overflowFilled?: boolean }, persisted = false) {
    if (r.gained > 0) this.log(t('sys.exp_gain', { exp: r.gained }), '#ffe680');
    if ((r.overflowed ?? 0) > 0) this.log(`${t('sys.exp_gain', { exp: r.overflowed ?? 0 })}${t('realm.overflow_gain')}`, '#9a9a9a');
    if (r.overflowFilled) this.log(t('realm.overflow_full'), '#ffb0ff');
    if (r.levels) {
      this.levelUpFx(); this.log(t('sys.level_up', { level: this.prog.level }), '#7fffd4');
      this.player.maxHp = this.prog.maxHp; this.player.hp = this.prog.hp;
      if (!persisted) this.prog.persistSoon();
      this.maybeSpTip();
    }
    if (r.blocked) {
      if (r.gained === 0) this.log(t('realm.bottleneck'), '#ffb0ff');
      if (!this.breakthroughNotified) { this.breakthroughNotified = true; this.log(t('realm.bottleneck_tip', { realm: this.prog.realm.name, npc: '天剑宗接引使' }), '#ffb0ff'); }
    }
  }

  giveRewards(q: typeof QUESTS_REF[string], broke: boolean, daily?: DailyQuestReward, settled?: QuestRewardSettlement) {
    // 日常由 QuestSystem 完整结算并保存；没有本次收据时不走普通任务发奖路径。
    if (q.daily) {
      if (!daily) return;
      this.log(t('quest.complete', { name: questName(q) }), '#ffe680');
      this.applyExp(daily.exp, true);
      if (q.rewards.spiritStone) this.log(t('sys.stone_gain', { n: q.rewards.spiritStone }), '#7ff0d0');
      for (const it of daily.items) this.log(t('sys.item_gain', { item: ITEMS[it.item]?.name ?? it.item, n: it.count }), '#ffffff');
      for (const id of daily.skills) this.log(t('skill.learned', { skill: SKILLS[id]?.name ?? id }), '#9fd0ff');
      this.log(t('sect.ui.contribution', { contribution: this.prog.sectContribution }), '#ffd23a');
      this.player.syncAppearance(); this.skillWindow.refresh();
      this.player.maxHp = this.prog.maxHp; this.player.hp = this.prog.hp;
      this.maybeSpTip();
      return;
    }
    // 普通任务同样先原子结算并保存；没有成功收据就不展示完成或再发奖励。
    if (!settled) return;
    const rw = q.rewards;
    const cls = classForQuest(q.id);
    const job = cls?.id ?? rw.job;
    this.log(t('quest.complete', { name: questName(q) }), '#ffe680');
    if (broke) {
      this.player.maxHp = this.prog.maxHp; this.player.hp = this.prog.hp;
      this.log(`突破成功，当前境界 ${this.prog.realmName}`, '#ffb0ff');
      if (this.prog.lastOverflowReturned > 0) this.log(`溢出修为返还 ${this.prog.lastOverflowReturned}`, '#c8c8c8');
      if (this.prog.breakthroughBonusLevels > 0) { this.levelUpFx(); this.log(t('sys.level_up', { level: this.prog.level }), '#7fffd4'); }
    }
    this.applyExp(settled.exp, true);
    if (rw.spiritStone) this.log(`获得灵石 ${rw.spiritStone}`, '#7ff0d0');
    for (const it of settled.items) {
      if (ITEMS[it.item]?.type === 'equip') this.log(`获得 ${ITEMS[it.item].name}${it.equipped ? '（已自动装备）' : ''}`, '#9fd0ff');
      else this.log(`获得 ${ITEMS[it.item]?.name ?? it.item} ×${it.count}`, '#ffffff');
    }
    const ids = settled.skills;
    if (job && ids.includes('whirl_sword') && ids.includes('light_body')) this.log(t('skill.job_advance'), '#ffd23a');
    else if (ids.includes('sword_qi_slash')) this.log(t('skill.learned_first'), '#9fd0ff');
    else for (const id of ids) this.log(t('skill.learned', { skill: SKILLS[id]?.name ?? id }), '#9fd0ff');
    if (job && !(ids.includes('whirl_sword') && ids.includes('light_body'))) this.log(`拜入${cls?.name ?? job}，已学本宗一转功法`, '#ffd23a');
    this.player.syncAppearance();
    this.skillWindow.refresh();
    this.player.maxHp = this.prog.maxHp; this.player.hp = this.prog.hp;
    this.maybeSpTip();
  }

  /** 突破失败演出（v0.4 筑基台用）：同样放在 dim 层上方 */
  playBreakthroughFail(x: number, y: number) {
    if (!this.textures.exists('fx_breakthrough_fail')) return;
    const fx = this.add.sprite(x, y, 'fx_breakthrough_fail').setOrigin(0.5, 1).setDepth(165);
    fx.play('fx_breakthrough_fail_play'); fx.once(Phaser.Animations.Events.ANIMATION_COMPLETE, () => fx.destroy());
  }

  tryAddPoint(id: string) {
    const r = this.prog.addSkillPoint(id);
    if (r.ok) this.log(t('skill.sp_left', { n: this.prog.spLeftFor(1) }), '#ffe680');
    else if (r.reason === 'req') this.log(t('skill.req_block', { req: r.req || '前置不足' }), '#ffb0b0');
    else if (r.reason === 'sp') this.log(t('skill.no_sp'), '#ffb0b0');
    else if (r.reason === 'max') this.log(t('skill.maxed'), '#ffb0b0');
    else if (r.reason === 'locked') this.log(this.prog.skillsUnlocked ? '当前职业不能修习这门功法' : t('skill.locked'), '#ffb0b0');
    this.skillWindow.refresh();
  }

  maybeSpTip() {
    if (this.prog.spTipShown || this.prog.spLeftFor(1) <= 0) return;
    this.prog.spTipShown = true;
    this.log(t('tip.first_sp'), '#ffe680');
    this.prog.persistSoon();
  }

  /** 自然回蓝：每 5 秒最大灵力 × MP_REGEN_FRACTION_PER_5S，再加上被动的 mpRegenPer10s。 */
  private regenMp(deltaMs: number) {
    const pr = this.prog;
    if (this.player.dead) return;
    if (pr.mp >= pr.maxMp) { pr.mp = pr.maxMp; this.mpPool = 0; return; }
    const perMs = pr.maxMp * MP_REGEN_FRACTION_PER_5S / 5000 + pr.passiveBonus('mpRegenPer10s') / 10000;
    this.mpPool += perMs * deltaMs;
    if (this.mpPool >= 1) {
      const add = Math.floor(this.mpPool);
      this.mpPool -= add;
      pr.mp = Math.min(pr.maxMp, pr.mp + add);
    }
  }

  /** 演出：突破 / 转职 */
  playCue(cue: string, next: () => void, title?: string) {
    this.senseCueDepth++;
    const p = this.player, cam = this.cameras.main;
    const dim = this.add.rectangle(640, 360, 1280, 720, 0x000000, 0).setScrollFactor(0).setDepth(150);
    this.tweens.add({ targets: dim, fillAlpha: 0.6, duration: 400 });
    if (p.atlas) p.play(p.animationKey('sit'));
    // 主角和突破特效都要在 dim 层（150）上方，否则会被一起压暗：back 155 < 主角 158 < front 165
    const pDepth = p.depth; p.setDepth(158);
    if (cue === 'breakthrough' && this.textures.exists('fx_breakthrough_success')) {
      // front_07 爆光对准 1900ms 的闪白：8fps 下第 7 帧在 750ms，所以 1150ms 开播
      this.time.delayedCall(1150, () => {
        for (const [layer, d] of [['back', 155], ['front', 165]] as const) {
          const fx = this.add.sprite(p.x, p.y, 'fx_breakthrough_success').setOrigin(0.5, 1).setDepth(d);
          fx.play('fx_breakthrough_success_' + layer); fx.once(Phaser.Animations.Events.ANIMATION_COMPLETE, () => fx.destroy());
        }
      });
    }
    const col = cue === 'breakthrough' ? 0xfff0a0 : 0x9fe8ff;
    for (let i = 0; i < 24; i++) {                       // 灵气从四周汇入
      const a = (i / 24) * Math.PI * 2, r = 220;
      const dot = this.add.circle(p.x + Math.cos(a) * r, p.y - 40 + Math.sin(a) * r, 5, col).setDepth(160).setBlendMode(Phaser.BlendModes.ADD);
      this.tweens.add({ targets: dot, x: p.x, y: p.y - 40, alpha: 0.2, delay: i * 40, duration: 900, onComplete: () => dot.destroy() });
    }
    this.time.delayedCall(1900, () => {
      cam.flash(400, 255, 240, 180);
      const ring = this.add.circle(p.x, p.y - 40, 30, col, 0.7).setDepth(160).setBlendMode(Phaser.BlendModes.ADD);
      this.tweens.add({ targets: ring, scale: 8, alpha: 0, duration: 700, onComplete: () => ring.destroy() });
      const t = this.add.text(640, 260, title ?? (cue === 'breakthrough' ? '突破成功 · 炼气期' : '拜入天剑宗 · 剑徒'), { fontFamily: 'serif', fontSize: '44px', color: '#fff6c8', stroke: '#7a4a00', strokeThickness: 6 }).setOrigin(0.5).setScrollFactor(0).setDepth(170).setAlpha(0);
      this.tweens.add({ targets: t, alpha: 1, y: 240, duration: 500, hold: 1200, yoyo: true, onComplete: () => {
        t.destroy(); this.tweens.add({ targets: dim, fillAlpha: 0, duration: 300, onComplete: () => { dim.destroy(); p.setDepth(pDepth); this.senseCueDepth = Math.max(0, this.senseCueDepth - 1); next(); } });
      } });
    });
  }

  /** reach 目标：走到对应地图物件附近就算到达 */
  checkReach() {
    const p = this.player;
    for (const o of this.map.objects) if (o.type === 'chest' && this.senseMap?.objectVisible(o) !== false && Math.abs(o.x - p.x) < 48 && Math.abs(o.y - p.y) < 48) this.quests.onReach(o.name);
  }

  tryOpenChest() {
    const p = this.player;
    for (const o of this.map.objects) {
      if (o.type !== 'chest' || this.senseMap?.objectVisible(o) === false || Math.abs(o.x - p.x) > 32 || Math.abs(o.y - p.y) > 40) continue;
      const key = `${this.map.id}:${o.name}`;
      if (this.prog.openedChests.includes(key)) return;
      this.prog.openedChests.push(key);
      this.prog.persistSoon();
      this.openedChests.add(key);
      const chest = this.children.getByName('chest:' + o.name);
      if (chest instanceof Phaser.GameObjects.Sprite) {
        openPropChest(this, chest, resolveSecretProp(o)!.atlas);
      } else if (chest instanceof Phaser.GameObjects.Rectangle) chest.setFillStyle(0x7a5a3a);
      this.spawnDrop(o.x, o.y - 30, o.props.loot, o.props.count ?? 1);
      return;
    }
  }

  // ---------------- 表现 ----------------
  log(msg: string, color: string, rankIcon?: string) {
    const hist = ((window as any).__logs ??= []) as string[]; hist.push(msg); if (hist.length > 100) hist.shift();   // 测试读系统消息
    const badge = sectRankIcon(this, rankIcon);
    const t = this.add.text(badge ? 42 : 16, 0, msg, { fontFamily: 'sans-serif', fontSize: '14px', color, stroke: '#000000', strokeThickness: 3 }).setOrigin(0, 1).setScrollFactor(0).setDepth(102);
    const image = badge ? this.add.image(26, 0, badge.texture, badge.frame).setName('sect-rank-log').setDisplaySize(20, 20).setScrollFactor(0).setDepth(102) : undefined;
    if (image) {
      this.logBadges.set(t, image);
      t.once(Phaser.GameObjects.Events.DESTROY, () => { image.destroy(); this.logBadges.delete(t); });
    }
    this.logs.push(t);
    if (this.logs.length > 6) this.logs.shift()!.destroy();
    const base = this.hudKit ? 596 : 668;   // 新 HUD 状态区从 y=604 开始，系统消息挪到它上面
    this.logs.forEach((l, i) => {
      l.setY(base - (this.logs.length - 1 - i) * 20);
      this.logBadges.get(l)?.setY(l.y - l.height / 2);
    });
    this.time.delayedCall(4000, () => { this.tweens.add({ targets: image ? [t, image] : t, alpha: 0, duration: 400, onComplete: () => { this.logs = this.logs.filter(x => x !== t); t.destroy(); } }); });
  }

  levelUpFx() {
    const t = this.add.text(this.player.x, this.player.y - 100, 'LEVEL UP', { fontFamily: 'Arial Black, sans-serif', fontSize: '28px', color: '#fff27a', stroke: '#8a5a00', strokeThickness: 5 }).setOrigin(0.5).setDepth(50);
    this.tweens.add({ targets: t, y: t.y - 50, alpha: 0, duration: 1500, onComplete: () => t.destroy() });
    const ring = this.add.circle(this.player.x, this.player.y - 30, 20, 0xfff27a, 0.5).setDepth(9);
    this.tweens.add({ targets: ring, scale: 4, alpha: 0, duration: 600, onComplete: () => ring.destroy() });
  }

  damageNumber(x: number, y: number, n: number, color: string, stroke: string) {
    // 位图字：玩家受伤用朱红，其余用伤害白（只含 0–9、+、升级）
    const font = color === '#c45cff' ? 'ui_hud_font_hurt' : 'ui_hud_font_white';
    if (this.cache.bitmapFont.exists(font)) {
      const bt = this.add.bitmapText(x, y, font, String(n)).setOrigin(0.5).setDepth(50);
      this.tweens.add({ targets: bt, y: y - 40, alpha: 0, duration: 700, ease: 'Cubic.easeOut', onComplete: () => bt.destroy() });
      return;
    }
    const t = this.add.text(x, y, String(n), { fontFamily: 'Arial Black, sans-serif', fontSize: '24px', color, stroke, strokeThickness: 4 }).setOrigin(0.5).setDepth(50);
    this.tweens.add({ targets: t, y: y - 40, alpha: 0, duration: 700, ease: 'Cubic.easeOut', onComplete: () => t.destroy() });
  }

  puff(x: number, y: number) {
    const c = this.add.circle(x, y, 10, 0xffffff, 0.8).setDepth(9);
    this.tweens.add({ targets: c, scale: 2.5, alpha: 0, duration: 250, onComplete: () => c.destroy() });
